-- =============================================================================
-- 0005_subscriptions.sql — Subscriptions: monthly / annual access to every course.
-- =============================================================================

-- =============================================================================
-- 0005 — Subscriptions: monthly / annual access to every course.
--
-- A subscription is keyed by email like a purchase, one row per email: a customer either has a
-- subscription or does not, and renewals extend the same row. Access is time-boxed
-- (`expires_at`), which is the whole difference from a purchase — nothing else in the schema
-- changes: `my_entitlements` simply lists every course while the subscription is live, so the
-- app, the leaderboard and the storage policies keep working on course ids.
-- "Live" is one function, subscription_live(): active or cancelled, and the paid period not over.
--
-- Writers, in order of trust:
--   create_subscription_order()   anonymous visitor → a pending intent (email ↔ plan)
--   apply_subscription_payment()  the payment webhook (service role) → activate / extend
--   admin_set_subscription()      the coach → grant, extend, cancel by hand
-- Customers never write the table and read it only through `my_subscription`.
-- =============================================================================

create table if not exists public.subscriptions (
  id           uuid primary key default gen_random_uuid(),
  email        citext not null unique,
  plan         text not null check (plan in ('monthly', 'annual')),
  status       text not null default 'pending' check (status in ('pending', 'active', 'cancelled')),
  -- Access is live while status = 'active' and now() < expires_at. A cancelled subscription keeps
  -- its expires_at: the customer paid for that period and keeps it.
  started_at   timestamptz,
  expires_at   timestamptz,
  -- 'landing' / 'app' for intents, 'prodamus' for webhook payments, 'admin' for manual grants.
  source       text,
  -- The provider's own subscription / order id, for support and for idempotent webhooks.
  provider_ref text,
  locale       text,
  note         text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

comment on table public.subscriptions is
  'Monthly / annual access to every course. pending → active (payment) → cancelled; access ends at expires_at.';

alter table public.subscriptions drop constraint if exists subscriptions_email_len;
alter table public.subscriptions add constraint subscriptions_email_len
  check (length(email::text) <= 254) not valid;
alter table public.subscriptions drop constraint if exists subscriptions_source_len;
alter table public.subscriptions add constraint subscriptions_source_len
  check (source is null or length(source) <= 40) not valid;
alter table public.subscriptions drop constraint if exists subscriptions_provider_ref_len;
alter table public.subscriptions add constraint subscriptions_provider_ref_len
  check (provider_ref is null or length(provider_ref) <= 120) not valid;
alter table public.subscriptions drop constraint if exists subscriptions_locale_fmt;
alter table public.subscriptions add constraint subscriptions_locale_fmt
  check (locale is null or locale in ('ru', 'en')) not valid;
alter table public.subscriptions drop constraint if exists subscriptions_note_len;
alter table public.subscriptions add constraint subscriptions_note_len
  check (note is null or length(note) <= 500) not valid;

create index if not exists subscriptions_status_created_idx on public.subscriptions (status, created_at desc);

drop trigger if exists subscriptions_touch on public.subscriptions;
create trigger subscriptions_touch
  before update on public.subscriptions
  for each row execute function public.set_updated_at();

alter table public.subscriptions enable row level security;

-- Same access model as purchases: admins read and write through the API, customers see only
-- the `my_subscription` view (no note, no provider reference).
drop policy if exists "subscriptions: admins all" on public.subscriptions;
create policy "subscriptions: admins all"
  on public.subscriptions for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

revoke all on public.subscriptions from anon, authenticated;
grant select, insert, update, delete on public.subscriptions to authenticated;

-- -----------------------------------------------------------------------------
-- subscription_live — the one definition of "has access": the paid period is not over.
-- A cancelled subscription is live until its expires_at — cancelling stops renewals, it never
-- takes away time that was paid for. Pending never is.
-- -----------------------------------------------------------------------------
create or replace function public.subscription_live(p_status text, p_expires_at timestamptz)
returns boolean
language sql
stable
as $$
  select p_status in ('active', 'cancelled') and p_expires_at is not null and p_expires_at > now();
$$;

-- Views check function rights against the caller, so the predicate must be executable by users.
revoke execute on function public.subscription_live(text, timestamptz) from public, anon;
grant execute on function public.subscription_live(text, timestamptz) to authenticated;

-- -----------------------------------------------------------------------------
-- subscription_period — how long one payment buys.
-- -----------------------------------------------------------------------------
create or replace function public.subscription_period(p_plan text)
returns interval
language sql
immutable
as $$
  select case p_plan when 'annual' then interval '1 year' else interval '1 month' end;
$$;

revoke execute on function public.subscription_period(text) from public, anon, authenticated;

-- -----------------------------------------------------------------------------
-- my_subscription — the signed-in user's own row, without the coach's fields.
-- -----------------------------------------------------------------------------
drop view if exists public.my_subscription;
create view public.my_subscription
with (security_invoker = false)
as
  select s.plan, s.status, s.started_at, s.expires_at,
         public.subscription_live(s.status, s.expires_at) as is_live
  from public.subscriptions s
  where s.email = public.current_email();

revoke all on public.my_subscription from anon, authenticated;
grant select on public.my_subscription to authenticated;

-- -----------------------------------------------------------------------------
-- my_entitlements — purchased courses, plus every course while a subscription is live.
-- Replaces the view from 0002; the column list is unchanged so the client needs no change.
-- -----------------------------------------------------------------------------
drop view if exists public.my_entitlements;
create view public.my_entitlements
with (security_invoker = false)
as
  select p.course_id, p.activated_at
  from public.purchases p
  where p.status = 'active'
    and p.email = public.current_email()
  union
  select c.id as course_id, s.started_at as activated_at
  from public.subscriptions s
  cross join public.courses c
  where public.subscription_live(s.status, s.expires_at)
    and s.email = public.current_email();

revoke all on public.my_entitlements from anon, authenticated;
grant select on public.my_entitlements to authenticated;

-- -----------------------------------------------------------------------------
-- create_subscription_order — the landing / app "subscribe" form. Anonymous.
-- Records the intent so the payment can be matched to an email; never grants access.
-- Reuses the pending-order throttle of create_order() through the same table of buckets.
-- -----------------------------------------------------------------------------
create or replace function public.create_subscription_order(
  p_email  text,
  p_plan   text,
  p_locale text default 'ru',
  p_source text default 'landing'
)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_email  citext;
  v_locale text;
  v_source text;
  v_id     uuid;
begin
  v_email := public.normalize_email(p_email);

  if p_plan is null or p_plan not in ('monthly', 'annual') then
    raise exception 'invalid_plan' using errcode = 'P0001', hint = 'monthly or annual';
  end if;

  v_locale := case when p_locale in ('ru', 'en') then p_locale else 'ru' end;
  v_source := left(coalesce(nullif(trim(p_source), ''), 'landing'), 40);

  -- One pending intent per email is enough; a live subscription is never downgraded by a form.
  insert into public.subscriptions (email, plan, status, source, locale)
  values (v_email, p_plan, 'pending', v_source, v_locale)
  on conflict (email) do update
    set plan       = case when public.subscription_live(subscriptions.status, subscriptions.expires_at)
                          then subscriptions.plan else excluded.plan end,
        source     = case when public.subscription_live(subscriptions.status, subscriptions.expires_at)
                          then subscriptions.source else excluded.source end,
        locale     = coalesce(excluded.locale, subscriptions.locale),
        updated_at = now()
  returning id into v_id;

  return v_id;
end;
$$;

revoke execute on function public.create_subscription_order(text, text, text, text) from public;
grant execute on function public.create_subscription_order(text, text, text, text) to anon, authenticated;

-- -----------------------------------------------------------------------------
-- apply_subscription_payment — called by the payment webhook with the service role.
-- Idempotent per provider reference: the same notification delivered twice extends once.
-- A payment while the subscription is still live extends from expires_at (a renewal);
-- after a gap it starts from now (a return), so nobody is charged for months they were away.
-- -----------------------------------------------------------------------------
create or replace function public.apply_subscription_payment(
  p_email        text,
  p_plan         text,
  p_provider_ref text default null,
  p_paid_at      timestamptz default now()
)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_email  citext;
  v_row    public.subscriptions%rowtype;
  v_from   timestamptz;
  v_ref    text;
  v_id     uuid;
begin
  -- Only the service role (the webhook) and the SQL editor: never a signed-in user.
  if coalesce(current_setting('request.jwt.claims', true), '') <> ''
     and coalesce(current_setting('request.jwt.claims', true)::json ->> 'role', '') <> 'service_role' then
    raise exception 'not_allowed' using errcode = '42501';
  end if;

  v_email := public.normalize_email(p_email);
  if p_plan is null or p_plan not in ('monthly', 'annual') then
    raise exception 'invalid_plan' using errcode = 'P0001';
  end if;
  v_ref := left(nullif(trim(p_provider_ref), ''), 120);

  select * into v_row from public.subscriptions where email = v_email;

  if found and v_ref is not null and v_row.provider_ref = v_ref then
    return v_row.id; -- the same payment, delivered again
  end if;

  v_from := case
    when found and v_row.status in ('active', 'cancelled') and v_row.expires_at > p_paid_at then v_row.expires_at
    else p_paid_at
  end;

  insert into public.subscriptions (email, plan, status, started_at, expires_at, source, provider_ref)
  values (v_email, p_plan, 'active', p_paid_at, v_from + public.subscription_period(p_plan), 'prodamus', v_ref)
  on conflict (email) do update
    set plan         = excluded.plan,
        status       = 'active',
        started_at   = coalesce(subscriptions.started_at, excluded.started_at),
        expires_at   = excluded.expires_at,
        source       = 'prodamus',
        provider_ref = coalesce(excluded.provider_ref, subscriptions.provider_ref),
        updated_at   = now()
  returning id into v_id;

  return v_id;
end;
$$;

revoke execute on function public.apply_subscription_payment(text, text, text, timestamptz) from public, anon, authenticated;
grant execute on function public.apply_subscription_payment(text, text, text, timestamptz) to service_role;

-- -----------------------------------------------------------------------------
-- admin_set_subscription — grant, extend or cancel by hand (bank transfer, gift, support).
--   p_status 'active'    → expires_at = p_expires_at, or one period from now / from the current
--                          expiry when it is still in the future (an extension)
--   p_status 'cancelled' → access ends at the current expires_at (or now, if none)
-- -----------------------------------------------------------------------------
create or replace function public.admin_set_subscription(
  p_email      text,
  p_plan       text,
  p_status     text,
  p_expires_at timestamptz default null,
  p_note       text default null
)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_email   citext;
  v_row     public.subscriptions%rowtype;
  v_expires timestamptz;
  v_id      uuid;
begin
  if not public.is_admin() then
    raise exception 'not_admin' using errcode = '42501';
  end if;

  v_email := public.normalize_email(p_email);
  if p_plan is null or p_plan not in ('monthly', 'annual') then
    raise exception 'invalid_plan' using errcode = 'P0001';
  end if;
  if p_status is null or p_status not in ('active', 'cancelled') then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;

  select * into v_row from public.subscriptions where email = v_email;

  if p_status = 'active' then
    v_expires := coalesce(
      p_expires_at,
      (case when found and public.subscription_live(v_row.status, v_row.expires_at) then v_row.expires_at else now() end)
        + public.subscription_period(p_plan)
    );
  else
    if not found then
      raise exception 'not_found' using errcode = 'P0002';
    end if;
    v_expires := coalesce(v_row.expires_at, now());
  end if;

  insert into public.subscriptions (email, plan, status, started_at, expires_at, source, note)
  values (v_email, p_plan, p_status, now(), v_expires, 'admin', left(nullif(trim(p_note), ''), 500))
  on conflict (email) do update
    set plan       = excluded.plan,
        status     = excluded.status,
        started_at = coalesce(subscriptions.started_at, excluded.started_at),
        expires_at = excluded.expires_at,
        source     = 'admin',
        note       = coalesce(excluded.note, subscriptions.note),
        updated_at = now()
  returning id into v_id;

  return v_id;
end;
$$;

revoke execute on function public.admin_set_subscription(text, text, text, timestamptz, text) from public, anon;
grant execute on function public.admin_set_subscription(text, text, text, timestamptz, text) to authenticated;

-- =============================================================================
-- 0006_custom_workouts.sql — Exercise catalogue + custom workouts built by the coach.
-- =============================================================================

-- =============================================================================
-- 0006 — Exercise catalogue + custom workouts built by the coach.
--
-- Three tables and the glue that lets a coach-built workout be played and scored like a course
-- workout:
--   exercises        a database copy of the exercise library, so the coach can mark it up (video,
--                    tags) without a code change. Seeded from content by 0007_exercise_seed.sql.
--   custom_workouts  a workout the coach composes in the admin panel: a title and a JSON structure
--                    of sections (warm-up / main / cool-down) and items (an exercise with reps or
--                    seconds and a rest). It can carry a share_token (an in-app link) and is handed
--                    to people through assigned_workouts.
--   assigned_workouts  which email a custom workout is granted to — keyed by email like a purchase,
--                    so it can be granted before the person has signed up.
--
-- Playing one records a normal row in workout_sessions with course_id = 'custom' and node_id =
-- the workout's short_id (a regex-safe id that fits the sessions table), so points, the streak and
-- history all keep working. can_play_custom() replaces the has_entitlement() check for those rows.
-- Requires 0001_init.sql (workout_sessions, is_admin, current_email) and 0002 (normalize_email).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- exercises — the library, in the database, for the coach to build from and mark up.
-- Content stays the source of truth for the base fields (0007 re-seeds them); the markup columns
-- (video_ru / video_en / tags) are never overwritten by a re-seed, so hand edits survive.
-- -----------------------------------------------------------------------------
create table if not exists public.exercises (
  id              text primary key check (id ~ '^[a-z0-9_]{2,60}$'),
  name_ru         text not null,
  name_en         text,
  short_name_ru   text,
  description_ru  text,
  primary_muscle  text,
  muscles         text[] not null default '{}',
  pattern         text,
  equipment       text[] not null default '{}',
  level           int check (level is null or level between 1 and 3),
  unit            text not null default 'reps' check (unit in ('reps', 'seconds', 'meters', 'calories')),
  seconds_per_rep numeric,
  animation       text,
  video_ru        text,
  video_en        text,
  tags            text[] not null default '{}',
  is_test         boolean not null default false,
  sort_order      int not null default 0,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

comment on table public.exercises is
  'Exercise library in the database, for the workout builder and coach markup. Base fields seeded from content (0007); video/tags columns are hand-editable and never re-seeded.';

drop trigger if exists exercises_touch on public.exercises;
create trigger exercises_touch
  before update on public.exercises
  for each row execute function public.set_updated_at();

alter table public.exercises enable row level security;

-- Readable by any signed-in user (the builder and the catalogue screen); written only by admins.
drop policy if exists "exercises: read" on public.exercises;
create policy "exercises: read" on public.exercises for select to authenticated using (true);
drop policy if exists "exercises: admins write" on public.exercises;
create policy "exercises: admins write"
  on public.exercises for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

revoke all on public.exercises from anon, authenticated;
grant select, insert, update, delete on public.exercises to authenticated;

-- -----------------------------------------------------------------------------
-- exercises: the columns an admin-authored exercise needs.
--
-- The table above mirrors the compiled library, so it carries only what the builder reads.
-- Authoring a new exercise — a yoga pose, say — needs the teaching text too, and a flag that keeps
-- the generated re-seed from touching rows that were written by hand.
--
-- These live here, with the table, rather than in 0008 where the rest of the course builder is:
-- 0007_exercise_seed.sql is generated with a `where is_custom = false` guard on its upsert, and it
-- runs before 0008 would have added the column.
-- -----------------------------------------------------------------------------
alter table public.exercises add column if not exists description_en text;
-- how_to / cues / mistakes: arrays of {ru,en} strings, as ExerciseSchema defines them.
alter table public.exercises add column if not exists how_to jsonb not null default '[]'::jsonb;
alter table public.exercises add column if not exists cues jsonb not null default '[]'::jsonb;
alter table public.exercises add column if not exists mistakes jsonb not null default '[]'::jsonb;
alter table public.exercises add column if not exists breathing_ru text;
alter table public.exercises add column if not exists slug_ru text;
alter table public.exercises add column if not exists slug_en text;
-- A still image, for a pose whose video has not been shot yet.
alter table public.exercises add column if not exists image text;
alter table public.exercises add column if not exists author_id uuid references auth.users (id) on delete set null;

-- is_custom marks a row that was authored in the admin panel rather than generated from the
-- exercise files under content/exercises. scripts/content/gen-exercise-seed.mjs writes its upsert
-- to skip these, so a re-seed can never overwrite a pose the coach wrote.
--
-- (Line comments, not a block: Postgres nests block comments, so a path containing a slash-star
-- would open a second level and swallow the rest of the file.)
alter table public.exercises add column if not exists is_custom boolean not null default false;

comment on column public.exercises.is_custom is
  'True for an exercise authored in the admin panel. The generated seed (0007) never updates these rows.';

-- animation names a pose set defined in src/components/anim/poses — code the admin cannot write.
-- An admin-authored exercise leads with its video or image instead, so the column must be nullable.
-- (It already is; asserted here so a future tightening does not break authoring.)
alter table public.exercises alter column animation drop not null;

-- -----------------------------------------------------------------------------
-- custom_workouts — a workout the coach composed.
-- -----------------------------------------------------------------------------
create table if not exists public.custom_workouts (
  id           uuid primary key default gen_random_uuid(),
  -- A regex-safe id for the sessions table (course_id/node_id/workout_id are ^[a-z0-9_]{2,40}$).
  short_id     text not null unique check (short_id ~ '^[a-z0-9_]{2,40}$'),
  author_id    uuid references auth.users (id) on delete set null,
  title        text not null check (length(title) between 1 and 120),
  description  text check (description is null or length(description) <= 1000),
  structure    jsonb not null,
  est_sec      int check (est_sec is null or est_sec between 0 and 21600),
  points       int check (points is null or points between 0 and 375),
  -- A non-null token means "shared by link": anyone signed in who has the link can open and do it.
  share_token  text unique check (share_token is null or share_token ~ '^[A-Za-z0-9_-]{16,64}$'),
  is_archived  boolean not null default false,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

comment on table public.custom_workouts is
  'Workouts the coach builds in the admin panel. Played as workout_sessions with course_id = custom.';

-- A structure is a few KB of JSON; 64 KB is generous and stops a client from parking blobs here.
alter table public.custom_workouts drop constraint if exists custom_workouts_structure_len;
alter table public.custom_workouts add constraint custom_workouts_structure_len
  check (octet_length(structure::text) <= 65536) not valid;

create index if not exists custom_workouts_created_idx on public.custom_workouts (created_at desc);

drop trigger if exists custom_workouts_touch on public.custom_workouts;
create trigger custom_workouts_touch
  before update on public.custom_workouts
  for each row execute function public.set_updated_at();

alter table public.custom_workouts enable row level security;

-- -----------------------------------------------------------------------------
-- assigned_workouts — which email each custom workout is granted to.
-- -----------------------------------------------------------------------------
create table if not exists public.assigned_workouts (
  custom_workout_id uuid not null references public.custom_workouts (id) on delete cascade,
  email             citext not null check (length(email::text) <= 254),
  assigned_by       uuid references auth.users (id) on delete set null,
  note              text check (note is null or length(note) <= 500),
  created_at        timestamptz not null default now(),
  primary key (custom_workout_id, email)
);

comment on table public.assigned_workouts is
  'A custom workout granted to an email (keyed by email like a purchase, so it can precede sign-up).';

create index if not exists assigned_workouts_email_idx on public.assigned_workouts (email);

alter table public.assigned_workouts enable row level security;

-- The person sees their own assignments; the coach reads and writes all of them.
drop policy if exists "assigned_workouts: own or admin read" on public.assigned_workouts;
create policy "assigned_workouts: own or admin read"
  on public.assigned_workouts for select
  to authenticated
  using (email = public.current_email() or public.is_admin());
drop policy if exists "assigned_workouts: admins write" on public.assigned_workouts;
create policy "assigned_workouts: admins write"
  on public.assigned_workouts for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

revoke all on public.assigned_workouts from anon, authenticated;
grant select, insert, update, delete on public.assigned_workouts to authenticated;

-- -----------------------------------------------------------------------------
-- custom_workouts policies. Admins do everything; a person may read a workout that is either
-- shared by link or assigned to them. Enumeration of shared workouts is prevented by reading them
-- only through get_shared_custom_workout(token), never by listing the table.
-- -----------------------------------------------------------------------------
drop policy if exists "custom_workouts: admins all" on public.custom_workouts;
create policy "custom_workouts: admins all"
  on public.custom_workouts for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

drop policy if exists "custom_workouts: read assigned" on public.custom_workouts;
create policy "custom_workouts: read assigned"
  on public.custom_workouts for select
  to authenticated
  using (
    exists (
      select 1 from public.assigned_workouts a
      where a.custom_workout_id = id and a.email = public.current_email()
    )
  );

revoke all on public.custom_workouts from anon, authenticated;
grant select, insert, update, delete on public.custom_workouts to authenticated;

-- -----------------------------------------------------------------------------
-- can_play_custom — may the caller record a session for the custom workout with this short_id?
-- True for an admin, for a workout assigned to the caller, or for a shared workout (the caller
-- reached it through its link). Used by the workout_sessions insert policy in place of
-- has_entitlement() when course_id = 'custom'.
-- -----------------------------------------------------------------------------
create or replace function public.can_play_custom(p_short text)
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
  select public.is_admin() or exists (
    select 1
    from public.custom_workouts w
    left join public.assigned_workouts a
      on a.custom_workout_id = w.id and a.email = public.current_email()
    where w.short_id = p_short
      and w.is_archived = false
      and (w.share_token is not null or a.email is not null)
  );
$$;

revoke execute on function public.can_play_custom(text) from public, anon;
grant execute on function public.can_play_custom(text) to authenticated;

-- -----------------------------------------------------------------------------
-- get_shared_custom_workout — resolve a share link to its workout, without exposing the table.
-- Returns nothing for an unknown or archived token.
-- -----------------------------------------------------------------------------
create or replace function public.get_shared_custom_workout(p_token text)
returns table (
  id uuid, short_id text, title text, description text, structure jsonb, est_sec int, points int
)
language sql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
  select w.id, w.short_id, w.title, w.description, w.structure, w.est_sec, w.points
  from public.custom_workouts w
  where w.share_token = p_token and w.is_archived = false;
$$;

revoke execute on function public.get_shared_custom_workout(text) from public, anon;
grant execute on function public.get_shared_custom_workout(text) to authenticated;

-- -----------------------------------------------------------------------------
-- my_custom_workouts — the custom workouts assigned to the signed-in user.
-- -----------------------------------------------------------------------------
drop view if exists public.my_custom_workouts;
create view public.my_custom_workouts
with (security_invoker = false)
as
  select w.id, w.short_id, w.title, w.description, w.structure, w.est_sec, w.points,
         a.created_at as assigned_at
  from public.assigned_workouts a
  join public.custom_workouts w on w.id = a.custom_workout_id
  where a.email = public.current_email() and w.is_archived = false;

revoke all on public.my_custom_workouts from anon, authenticated;
grant select on public.my_custom_workouts to authenticated;

-- -----------------------------------------------------------------------------
-- workout_sessions insert policy — allow custom-workout sessions (course_id = 'custom').
-- Everything else is unchanged: a course workout still needs an active entitlement.
-- -----------------------------------------------------------------------------
drop policy if exists "workout_sessions: owner insert" on public.workout_sessions;
create policy "workout_sessions: owner insert"
  on public.workout_sessions for insert
  to authenticated
  with check (
    user_id = auth.uid()
    and (
      (course_id <> 'custom' and public.has_entitlement(course_id))
      or (course_id = 'custom' and public.can_play_custom(node_id))
    )
  );

-- -----------------------------------------------------------------------------
-- admin_assign_custom_workout / admin_unassign_custom_workout — grant by email, normalized.
-- -----------------------------------------------------------------------------
create or replace function public.admin_assign_custom_workout(p_workout uuid, p_email text, p_note text default null)
returns void
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_email citext := public.normalize_email(p_email);
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if v_email is null or length(v_email::text) = 0 then
    raise exception 'invalid_email' using errcode = 'P0001';
  end if;
  insert into public.assigned_workouts (custom_workout_id, email, assigned_by, note)
  values (p_workout, v_email, auth.uid(), p_note)
  on conflict (custom_workout_id, email) do update set note = excluded.note;
end;
$$;

revoke execute on function public.admin_assign_custom_workout(uuid, text, text) from public, anon;
grant execute on function public.admin_assign_custom_workout(uuid, text, text) to authenticated;

create or replace function public.admin_unassign_custom_workout(p_workout uuid, p_email text)
returns void
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_email citext := public.normalize_email(p_email);
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  delete from public.assigned_workouts
  where custom_workout_id = p_workout and email = v_email;
end;
$$;

revoke execute on function public.admin_unassign_custom_workout(uuid, text) from public, anon;
grant execute on function public.admin_unassign_custom_workout(uuid, text) to authenticated;

-- =============================================================================
-- 0007_exercise_seed.sql — the exercise library, in the database.
-- =============================================================================

-- =============================================================================
-- Forma — 0007_exercise_seed: the exercise library, in the database.
--
-- GENERATED FILE — do not edit by hand.
-- Regenerate with:  node scripts/content/gen-exercise-seed.mjs
-- Source of truth:  content/exercises/*.ts (validated by src/content/registry.ts)
--
-- Requires 0006_custom_workouts.sql (the exercises table).
-- Upserts the descriptive fields; video_ru / video_en / tags are populated on first insert only
-- and are never overwritten, so coach markup in those columns survives a re-seed.
-- =============================================================================

insert into public.exercises (
  id, name_ru, name_en, short_name_ru, description_ru, primary_muscle, muscles, pattern,
  equipment, level, unit, seconds_per_rep, video_ru, video_en, tags, is_test, sort_order
) values
  ('air_squat', 'Приседания', 'Air squat', 'Приседания', 'Базовое движение всей программы: приседания без веса учат правильно сгибать колени и тазобедренные суставы, держать спину и работать всей ногой. Они нагружают квадрицепсы и ягодицы, разогревают суставы и лежат в основе прыжков, выпадов и приседаний с гантелями. В тесте мы считаем приседания за 60 секунд — это простой показатель выносливости ног.', 'quads', '{"quads","glutes","hamstrings","core"}', 'squat', '{"none"}', 1, 'reps', 2.5, 'storage:videos/shared/air_squat.ru.mp4', null, '{"lower","benchmark"}', true, 1),
  ('ankle_circles', 'Вращения стопами', 'Ankle circles', 'Вращения стопами', 'Вращения стопами завершают суставную гимнастику сверху вниз. Голеностоп — сустав, который в приседе решает, останутся ли пятки на полу, а в прыжках и джампинг-джеках принимает первый удар. Стоя на одной ноге, вторую приподними и покрути стопой в обе стороны; в задании время указано на одну ногу.', 'calves', '{"calves"}', 'mobility', '{"none"}', 1, 'seconds', null, 'storage:videos/shared/ankle_circles.ru.mp4', null, '{"warmup","mobility","lower"}', false, 2),
  ('arm_circles', 'Круги руками', 'Arm circles', 'Круги руками', 'Круги руками — динамическая разминка плечевых суставов. Они прогоняют кровь через ротаторную манжету и разогревают плечи, грудь и верх спины перед отжиманиями, жимами и любыми движениями над головой. Делай их до, а не вместо силовой работы — это подготовка, а не нагрузка. Половину времени крути вперёд, половину — назад.', 'shoulders', '{"shoulders","back"}', 'mobility', '{"none"}', 1, 'seconds', null, 'storage:videos/shared/arm_circles.ru.mp4', null, '{"warmup","mobility","upper"}', false, 3),
  ('band_pull_apart', 'Разведение резинки', 'Band pull-apart', 'Разведение', 'Разведение резинки — растягивание ленты перед собой прямыми руками. Упражнение будит задние дельты, ромбовидные и ротаторную манжету — мелкие мышцы, которые держат плечи в правильном положении и защищают их в отжиманиях и жимах над головой. Мы ставим его в разминку перед любой работой на верх тела и как «антидот» от сидения за компьютером.', 'shoulders', '{"shoulders","back"}', 'pull_horizontal', '{"bands"}', 1, 'reps', 2, null, null, '{"upper","pull","warmup","mobility"}', false, 4),
  ('band_row', 'Тяга резинки к поясу', 'Band row', 'Тяга резинки', 'Тяга резинки к поясу — горизонтальная тяга для середины спины, задних дельт и бицепсов. Резинка даёт нагрузку, которая растёт к концу движения, поэтому именно в точке сведения лопаток спина работает сильнее всего. Мы используем её, чтобы уравновесить отжимания, и как замену тягам с гантелями, когда их нет. Закрепи резинку за устойчивую опору на уровне груди или зацепи за стопы сидя на полу.', 'back', '{"back","lats","biceps","shoulders"}', 'pull_horizontal', '{"bands"}', 1, 'reps', 2, null, null, '{"upper","pull"}', false, 5),
  ('bear_crawl', 'Медвежья походка', 'Bear crawl', 'Медвежья походка', 'Медвежья походка — передвижение на четырёх точках с коленями, поднятыми на пару сантиметров над полом. Упражнение включает всё тело: плечи и руки держат вес, кор не даёт тазу качаться, ноги перебирают под нагрузкой. Это и координация, и сила, и кардио сразу; дома делай шаги вперёд-назад в пределах коврика.', 'shoulders', '{"shoulders","core","quads","triceps","full_body"}', 'locomotion', '{"none"}', 2, 'seconds', null, null, null, '{"cardio","core","upper"}', false, 6),
  ('bird_dog', 'Бёрд-дог', 'Bird dog', 'Бёрд-дог', 'Бёрд-дог — вытягивание противоположных руки и ноги из положения на четвереньках. Упражнение тренирует глубокие мышцы спины, ягодицы и равновесие, при этом почти не нагружает позвоночник — поэтому его назначают даже при болях в пояснице. Мы используем его в разминке, чтобы «включить» кор перед тягами и приседаниями. Повторения считаем суммарно на обе стороны.', 'back', '{"back","glutes","core","shoulders"}', 'core_anti_extension', '{"none"}', 1, 'reps', 3, null, null, '{"core","warmup","unilateral"}', false, 7),
  ('broad_jump', 'Прыжок в длину с места', 'Broad jump', 'Прыжок в длину', 'Прыжок в длину с места — базовое упражнение на взрывную силу ног: замах руками, мощное разгибание бёдер и полёт вперёд с мягким приземлением в присед. Он учит выдавать максимум силы за короткое время и правильно гасить удар, что переносится на любой прыжок, бег и подъём тяжестей. Прыгай на максимум, но каждое приземление должно быть устойчивым — без шага и подскока.', 'glutes', '{"glutes","quads","hamstrings","calves"}', 'jump', '{"none"}', 2, 'reps', 4, null, null, '{"lower","explosive"}', false, 8),
  ('burpee', 'Бёрпи', 'Burpee', 'Бёрпи', 'Бёрпи — визитная карточка кроссфита: упор лёжа, отжимание, прыжок к ногам и выпрыгивание с хлопком над головой. Оно грузит всё тело сразу и разгоняет пульс быстрее любого другого упражнения без оборудования, поэтому стоит в наших метконах и в тесте на выносливость (бёрпи за 60 секунд). Держи ровный темп — лучше 12 чистых бёрпи, чем 20 корявых.', 'full_body', '{"full_body","cardio","chest","quads","core"}', 'full_body', '{"none"}', 2, 'reps', 5, null, null, '{"cardio","explosive","benchmark"}', true, 9),
  ('cat_cow', 'Кошка-корова', 'Cat-cow', 'Кошка-корова', 'Кошка-корова — мягкое чередование прогиба и округления спины на четвереньках. Упражнение «оживляет» позвоночник: разгоняет кровь в мышцах вдоль спины, учит чувствовать нейтральное положение поясницы и снимает скованность после сидячего дня. Мы ставим его в начало разминки и в заминку. Одно повторение = кошка + корова.', 'back', '{"back","core"}', 'mobility', '{"mat"}', 1, 'reps', 4, 'storage:videos/shared/cat_cow.ru.mp4', null, '{"warmup","cooldown","mobility"}', false, 10),
  ('chair_dip', 'Обратные отжимания от стула', 'Bench dip', 'Обратные отжимания', 'Обратные отжимания от стула нагружают трицепсы и заднюю часть плеч — мышцы, которые в обычных отжиманиях работают вторыми номерами. Ты опираешься руками на край стула сзади и сгибаешь локти, опуская таз к полу. Чем дальше выпрямлены ноги, тем тяжелее; согнутые колени делают упражнение доступным для любого уровня.', 'triceps', '{"triceps","shoulders","chest"}', 'push_vertical', '{"chair"}', 2, 'reps', 2.5, 'storage:videos/shared/chair_dip.ru.mp4', null, '{"upper","push"}', false, 11),
  ('child_pose', 'Поза ребёнка', 'Child''s pose', 'Поза ребёнка', 'Поза ребёнка — положение отдыха из йоги, которым мы заканчиваем тренировку: таз опускается на пятки, лоб — на коврик, руки вытянуты вперёд. Она мягко растягивает спину, широчайшие и плечи, опускает пульс и переключает тебя из режима нагрузки в режим восстановления. Здесь главное — дыхание, а не глубина.', 'back', '{"back","lats","shoulders"}', 'mobility', '{"mat"}', 1, 'seconds', null, 'storage:videos/shared/child_pose.ru.mp4', null, '{"cooldown","mobility"}', false, 12),
  ('db_clean', 'Взятие гантелей на грудь', 'Dumbbell clean', 'Взятие на грудь', 'Взятие на грудь — подъём двух гантелей с пола на плечи одним движением. Ты разгоняешь их ногами и тазом, как в становой, а затем быстро подсаживаешься под вес и ловишь его на плечах. Упражнение учит взрывному разгибанию и мягкому приёму — навыкам, из которых складываются рывок и любая быстрая работа с весом. Это и способ безопасно поднять гантели на плечи перед приседом или жимом.', 'glutes', '{"glutes","hamstrings","quads","back","shoulders","core"}', 'olympic', '{"dumbbells"}', 2, 'reps', 2.5, null, null, '{"explosive","lower","upper"}', false, 13),
  ('db_deadlift', 'Становая тяга с гантелями', 'Dumbbell deadlift', 'Становая', 'Становая тяга с гантелями — подъём веса с пола за счёт разгибания бёдер и колен с прямой спиной. Это самое важное движение для задней поверхности тела: ягодицы, бицепсы бедра и разгибатели спины учатся работать вместе, а ты — правильно поднимать любой предмет с пола. Гантели стоят по бокам от стоп, поэтому траектория короткая и удобная для новичка.', 'glutes', '{"glutes","hamstrings","back","quads","core"}', 'hinge', '{"dumbbells"}', 1, 'reps', 3, null, null, '{"lower"}', false, 14),
  ('db_devil_press', 'Дьявольский жим', 'Devil press', 'Дьявольский жим', 'Дьявольский жим — бёрпи с двумя гантелями, которое заканчивается их выбросом над головой. Ты опускаешься в упор лёжа, держась за гантели, отжимаешься, встаёшь и одним махом поднимаешь обе гантели над головой. Это самое требовательное упражнение курса: всё тело, максимальный пульс и техника рывка под усталостью. Ставим его только после того, как бёрпи и рывок гантели выполняются чисто.', 'full_body', '{"full_body","glutes","shoulders","chest","core","cardio"}', 'full_body', '{"dumbbells"}', 3, 'reps', 6, null, null, '{"cardio","explosive","benchmark"}', false, 15),
  ('db_floor_press', 'Жим гантелей лёжа с пола', 'Dumbbell floor press', 'Жим с пола', 'Жим гантелей лёжа с пола — домашняя замена жиму лёжа на скамье. Пол останавливает локти в нижней точке, поэтому амплитуда короче, плечи в безопасности, а нагрузка на грудь и трицепсы остаётся честной. Это главный горизонтальный жим с весом в программе: он позволяет прогрессировать там, где отжимания уже стали лёгкими.', 'chest', '{"chest","triceps","shoulders"}', 'push_horizontal', '{"dumbbells"}', 1, 'reps', 2.5, null, null, '{"upper","push"}', false, 16),
  ('db_front_squat', 'Фронтальный присед с гантелями', 'Dumbbell front squat', 'Фронтальный присед', 'Фронтальный присед с гантелями — приседание с двумя гантелями на плечах. Вес вдвое больше, чем в гоблет-приседе, и держать его нужно локтями вверх, поэтому корпус и верх спины работают почти так же, как ноги. Это главное силовое приседание курса с гантелями и половина трастера: освоив его, ты готов соединить присед с жимом.', 'quads', '{"quads","glutes","core","back","shoulders"}', 'squat', '{"dumbbells"}', 2, 'reps', 3, null, null, '{"lower"}', false, 17),
  ('db_goblet_squat', 'Гоблет-присед с гантелью', 'Goblet squat', 'Гоблет-присед', 'Гоблет-присед — приседание с гантелью, прижатой к груди обеими руками, как кубок. Вес перед корпусом сам выставляет технику: заставляет держать грудь вверх, садиться между коленей и не заваливаться вперёд. Это первое приседание с отягощением в программе и лучший способ научиться приседать глубоко и чисто. Одной гантели достаточно — держи её за верхний диск вертикально.', 'quads', '{"quads","glutes","core","back"}', 'squat', '{"dumbbells"}', 1, 'reps', 3, null, null, '{"lower"}', false, 18),
  ('db_lunge', 'Обратные выпады с гантелями', 'Dumbbell reverse lunge', 'Выпады с гантелями', 'Обратные выпады с гантелями — те же выпады назад, но с гантелями в опущенных руках. Дополнительный вес нагружает ягодицы и квадрицепсы каждой ноги по отдельности и заставляет корпус держать равновесие. Это лучшее упражнение курса против асимметрии ног и для сильных ягодиц; шаг назад, а не вперёд, бережёт колени. Повторения считаем суммарно, чередуя ноги.', 'quads', '{"quads","glutes","hamstrings","core"}', 'lunge', '{"dumbbells"}', 2, 'reps', 3, null, null, '{"lower","unilateral"}', false, 19),
  ('db_push_press', 'Швунг с гантелями', 'Dumbbell push press', 'Швунг', 'Швунг — жим над головой с коротким подседом и толчком ногами. Разгон снизу позволяет поднять больше веса и сделать больше повторений, чем в строгом жиме, а ещё учит передавать силу от ног к рукам через жёсткий корпус. Это тот же навык, что в трастере и рывке, только в самой простой форме. Подсед должен быть быстрым и неглубоким.', 'shoulders', '{"shoulders","triceps","quads","glutes","core"}', 'push_vertical', '{"dumbbells"}', 2, 'reps', 2, null, null, '{"upper","push","explosive"}', false, 20),
  ('db_rdl', 'Румынская тяга с гантелями', 'Dumbbell Romanian deadlift', 'Румынская тяга', 'Румынская тяга — наклон с гантелями на почти прямых ногах: движение идёт только в тазобедренном суставе, а гантели скользят вдоль бёдер вниз и вверх. В отличие от классической становой здесь вес не ставится на пол, и задняя поверхность бедра работает под постоянным натяжением. Это главное упражнение курса для бицепсов бедра и ягодиц и подготовка к махам гирей.', 'hamstrings', '{"hamstrings","glutes","back","core"}', 'hinge', '{"dumbbells"}', 2, 'reps', 3.5, null, null, '{"lower"}', false, 21),
  ('db_renegade_row', 'Тяга ренегата', 'Renegade row', 'Тяга ренегата', 'Тяга ренегата — тяга гантели к поясу из положения планки с опорой на вторую гантель. Пока одна рука тянет, весь корпус и опорное плечо не дают тазу развернуться, поэтому это одновременно упражнение на спину, пресс и стабильность плеч. Оно требует хорошей планки и уверенной тяги в наклоне. Одна тяга = одно повторение, руки чередуются.', 'back', '{"back","lats","core","obliques","shoulders","biceps"}', 'pull_horizontal', '{"dumbbells"}', 3, 'reps', 3, null, null, '{"upper","pull","core","unilateral"}', false, 22),
  ('db_row', 'Тяга гантели в наклоне', 'Dumbbell bent-over row', 'Тяга в наклоне', 'Тяга гантели в наклоне — основная горизонтальная тяга курса: ты наклоняешься с опорой свободной рукой на стул или колено и тянешь гантель к поясу. Работают широчайшие, ромбовидные, задние дельты и бицепс, а спина учится держать прямую линию под нагрузкой. Каждая сторона работает отдельно, поэтому слабая рука не прячется за сильной. Повторения указаны на каждую сторону.', 'lats', '{"lats","back","biceps","shoulders","core"}', 'pull_horizontal', '{"dumbbells"}', 1, 'reps', 2.5, null, null, '{"upper","pull","unilateral"}', false, 23),
  ('db_shoulder_press', 'Жим гантелей стоя', 'Dumbbell shoulder press', 'Жим стоя', 'Жим гантелей стоя — строгий жим над головой без помощи ног. Он строит плечи и трицепсы, а заодно учит держать корпус жёстким, когда вес уходит над головой: пресс и ягодицы не дают пояснице прогнуться. Это базовое вертикальное жимовое движение курса, из которого потом вырастают швунг и трастер.', 'shoulders', '{"shoulders","triceps","core"}', 'push_vertical', '{"dumbbells"}', 1, 'reps', 2.5, null, null, '{"upper","push"}', false, 24),
  ('db_snatch', 'Рывок гантели', 'Dumbbell snatch', 'Рывок гантели', 'Рывок гантели — подъём одной гантели с пола над головой одним непрерывным движением. Это самое взрывное упражнение курса с гантелями: сила рождается в ногах и тазе, проходит через жёсткий корпус и заканчивается фиксацией над головой. Рывок развивает мощность, координацию и выносливость сразу и берётся в работу только после уверенной становой и взятия на грудь. Гантель меняется каждое повторение, счёт — суммарно на обе руки.', 'glutes', '{"glutes","hamstrings","back","shoulders","core","cardio"}', 'olympic', '{"dumbbells"}', 3, 'reps', 2.5, null, null, '{"explosive","cardio","unilateral"}', false, 25),
  ('db_thruster', 'Трастер с гантелями', 'Dumbbell thruster', 'Трастер', 'Трастер — фронтальный присед, который без паузы переходит в жим гантелей над головой. Это одно из самых тяжёлых и полезных упражнений в кроссфите: работают ноги, ягодицы, плечи, трицепсы и кор, а пульс взлетает за несколько повторений. Секрет — не жать руками отдельно, а разогнать гантели ногами из приседа и просто «дожать» их наверху.', 'quads', '{"quads","glutes","shoulders","triceps","core","cardio"}', 'full_body', '{"dumbbells"}', 2, 'reps', 3.5, null, null, '{"lower","upper","push","cardio"}', false, 26),
  ('dead_bug', 'Мёртвый жук', 'Dead bug', 'Мёртвый жук', 'Мёртвый жук — самое безопасное упражнение на кор из всех, что мы используем: ты лежишь на спине и поочерёдно опускаешь противоположные руку и ногу, не отпуская поясницу от пола. Оно учит стабилизировать корпус, пока конечности двигаются, — это и есть работа пресса в реальной жизни и в спорте. Подходит при чувствительной спине и служит облегчённой заменой почти всем упражнениям на пресс. Повторения считаем суммарно на обе стороны.', 'core', '{"core","hip_flexors"}', 'core_anti_extension', '{"none"}', 1, 'reps', 3, 'storage:videos/shared/dead_bug.ru.mp4', null, '{"core","warmup"}', false, 27),
  ('dead_hang', 'Вис на перекладине', 'Dead hang', 'Вис', 'Вис на перекладине — простое удержание собственного веса на прямых руках. Он тренирует хват и предплечья, растягивает широчайшие и плечи и разгружает позвоночник после приседаний и тяг. Для новичка это первая ступень к подтягиваниям: пока хват не держит хотя бы 30 секунд, тянуться наверх рано. Ещё вис — отличная заминка для плеч в конце тренировки.', 'lats', '{"lats","back","shoulders","core"}', 'pull_vertical', '{"pullup_bar"}', 1, 'seconds', null, null, null, '{"upper","pull","cooldown"}', false, 28),
  ('diamond_push_up', 'Узкие отжимания', 'Diamond push-up', 'Узкие отжимания', 'Узкие отжимания — вариант с ладонями под грудью, где большие и указательные пальцы образуют «ромб». Узкая постановка переносит нагрузку с груди на трицепсы и делает каждое повторение заметно тяжелее. Это следующая ступень после классических отжиманий и хорошая подготовка к жимам с гантелями и отжиманиям на брусьях.', 'triceps', '{"triceps","chest","shoulders","core"}', 'push_horizontal', '{"none"}', 3, 'reps', 2.5, null, null, '{"upper","push"}', false, 29),
  ('double_under', 'Двойные прыжки на скакалке', 'Double-unders', 'Двойные', 'Двойные прыжки — два оборота скакалки за один прыжок. Это классический навык кроссфита: он требует быстрых кистей, чуть более высокого прыжка и, главное, спокойствия — как только ты начинаешь дёргаться, скакалка бьёт по ногам. Двойные разгоняют пульс сильнее любого другого упражнения без веса и учат тело работать расслабленно на высокой скорости. Осваивай их, когда одинарные идут без сбоев минуту подряд.', 'calves', '{"calves","quads","shoulders","core","cardio"}', 'jump', '{"jump_rope"}', 3, 'reps', 0.8, null, null, '{"cardio","explosive","benchmark"}', false, 30),
  ('elbow_wrist_circles', 'Вращения локтями и кистями', 'Elbow and wrist circles', 'Локти и кисти', 'Вращения локтями и кистями — часть суставной гимнастики перед любой работой на руках: отжиманиями, планками, червячками и бёрпи. Кисти принимают на себя вес тела в упоре лёжа, и без разогрева именно они первыми начинают ныть. Руки в стороны, локти согнуты, предплечья рисуют круги; затем ладони в замок и круги кистями.', 'shoulders', '{"shoulders","triceps"}', 'mobility', '{"none"}', 1, 'seconds', null, 'storage:videos/shared/elbow_wrist_circles.ru.mp4', null, '{"warmup","mobility","upper"}', false, 31),
  ('farmer_carry', 'Прогулка фермера', 'Farmer carry', 'Прогулка фермера', 'Прогулка фермера — ходьба с тяжёлыми гантелями или гирями в обеих руках. Самое «жизненное» упражнение в программе: оно тренирует хват, трапеции, кор и осанку ровно так, как их нагружают сумки из магазина и чемоданы. При этом техника проста, а травмироваться почти невозможно. Дома ходи туда-обратно по комнате заданное время — не останавливайся, пока идёт таймер.', 'back', '{"back","core","shoulders","glutes","full_body"}', 'carry', '{"dumbbells","kettlebell"}', 1, 'seconds', null, null, null, '{"carry","core","upper"}', false, 32),
  ('flutter_kick', 'Ножницы', 'Flutter kicks', 'Ножницы', 'Ножницы — попеременные махи прямыми ногами лёжа на спине. Пока ноги «плывут», пресс и сгибатели бедра работают на выносливость, а поясница учится оставаться прижатой к полу. Это отличный способ добить кор в конце комплекса или подержать пульс между силовыми блоками.', 'core', '{"core","hip_flexors","quads"}', 'core_flexion', '{"none"}', 2, 'seconds', null, null, null, '{"core","cardio"}', false, 33),
  ('glute_bridge', 'Ягодичный мостик', 'Glute bridge', 'Мостик', 'Ягодичный мостик учит включать ягодицы и заднюю поверхность бедра без нагрузки на колени и поясницу. Это первое движение в паттерне «тазовое разгибание», из которого потом вырастают румынская тяга и махи гирей. Мы используем его в разминке и в силовых блоках для новичков — и как облегчённую замену для сложных тяг.', 'glutes', '{"glutes","hamstrings","core"}', 'hinge', '{"none"}', 1, 'reps', 2.5, 'storage:videos/shared/glute_bridge.ru.mp4', null, '{"lower","warmup"}', false, 34),
  ('half_burpee', 'Полубёрпи', 'Half burpee', 'Полубёрпи', 'Полубёрпи — облегчённый вариант бёрпи без отжимания и без прыжка вверх: ты шагаешь или прыгаешь в упор лёжа и возвращаешься в положение стоя. Пульс всё равно растёт, а колени, запястья и плечи получают гораздо меньше нагрузки. Это отличный вход в бёрпи для новичков и разумная замена, когда нужно сохранить темп в длинном меткон-блоке.', 'full_body', '{"full_body","cardio","quads","core"}', 'full_body', '{"none"}', 1, 'reps', 4, null, null, '{"cardio"}', false, 35),
  ('hamstring_stretch', 'Растяжка задней поверхности бедра', 'Hamstring stretch', 'Задняя поверхность', 'Растяжка задней поверхности бедра расслабляет мышцы, которые тянут таз назад и не дают наклониться с прямой спиной. Она нужна после тяг, махов и бега, а ещё помогает глубже и правильнее приседать. Делай её в заминке на каждую ногу; время в задании указано на одну сторону.', 'hamstrings', '{"hamstrings","calves","glutes"}', 'mobility', '{"none"}', 1, 'seconds', null, 'storage:videos/shared/hamstring_stretch.ru.mp4', null, '{"cooldown","mobility","lower","unilateral"}', false, 36),
  ('hanging_knee_raise', 'Подъём коленей в висе', 'Hanging knee raise', 'Колени в висе', 'Подъём коленей в висе — упражнение на пресс, которое заодно тренирует хват и стабильность плеч. Вися на перекладине, ты подтягиваешь колени к груди, скручивая таз вверх, а не просто размахивая ногами. Это следующий шаг после подъёмов ног лёжа и подводка к подъёмам прямых ног, «носки к перекладине» и другим гимнастическим элементам.', 'core', '{"core","hip_flexors","lats","obliques"}', 'core_flexion', '{"pullup_bar"}', 2, 'reps', 2.5, null, null, '{"core","upper"}', false, 37),
  ('high_knees', 'Бег с высоким подниманием колен', 'High knees', 'Высокие колени', 'Бег на месте с высоким подниманием колен — быстрое кардио без оборудования, которое за секунды поднимает пульс и разогревает сгибатели бедра, икры и стопы. Мы ставим его в разминку перед прыжками и в кардио-интервалы как замену скакалке и скалолазу. Держи корпус вертикально и приземляйся мягко на переднюю часть стопы.', 'hip_flexors', '{"hip_flexors","quads","calves","cardio"}', 'locomotion', '{"none"}', 1, 'seconds', null, null, null, '{"cardio","warmup","lower"}', false, 38),
  ('hip_circles', 'Вращения тазом', 'Hip circles', 'Вращения тазом', 'Вращения тазом разминают тазобедренные суставы и поясницу перед приседаниями, выпадами и ягодичным мостом. Руки на поясе, ноги на ширине плеч, таз рисует большой медленный круг, будто ты крутишь обруч, а плечи и стопы остаются на месте. Половину времени крути в одну сторону, половину — в другую.', 'hip_flexors', '{"hip_flexors","glutes","core"}', 'mobility', '{"none"}', 1, 'seconds', null, 'storage:videos/shared/hip_circles.ru.mp4', null, '{"warmup","mobility","lower"}', false, 39),
  ('hip_flexor_stretch', 'Растяжка сгибателей бедра', 'Hip flexor stretch', 'Сгибатели бедра', 'Поза голубя раскрывает таз сразу с двух сторон: заднюю ногу тянет по передней поверхности бедра и подвздошно-поясничной, переднюю — по ягодичной и грушевидной. Эти мышцы укорачиваются от сидения и от бега, скалолаза и подъёмов ног, а свободный таз — это ровная поясница в приседе и полное разгибание в тягах и прыжках. Делай в заминке на каждую сторону; время в задании указано на одну сторону.', 'hip_flexors', '{"hip_flexors","quads","glutes"}', 'mobility', '{"none"}', 1, 'seconds', null, 'storage:videos/shared/hip_flexor_stretch.ru.mp4', null, '{"cooldown","mobility","lower","unilateral"}', false, 40),
  ('hollow_hold', 'Лодочка (hollow hold)', 'Hollow hold', 'Лодочка', 'Лодочка — гимнастическое удержание, в котором поясница прижата к полу, а руки и ноги вытянуты и висят над полом. Это лучший способ научиться держать пресс «замком» и не прогибать спину; такое положение тела нужно в отжиманиях, подтягиваниях и любом движении над головой. Нагрузка регулируется просто: чем ближе руки и ноги к полу, тем тяжелее.', 'core', '{"core","hip_flexors","quads"}', 'core_flexion', '{"none"}', 2, 'seconds', null, null, null, '{"core"}', false, 41),
  ('inchworm', 'Червячок', 'Inchworm', 'Червячок', 'Червячок, он же гусеница, — разминочное движение на всё тело: наклон, «шаги» ладонями вперёд до планки и обратные шаги стопами к рукам. Оно разогревает плечи, пресс и заднюю поверхность бедра и готовит запястья к отжиманиям и бёрпи. Отличный первый пункт разминки перед любой тренировкой без оборудования.', 'core', '{"core","shoulders","hamstrings","full_body"}', 'full_body', '{"none"}', 1, 'reps', 6, 'storage:videos/shared/inchworm.ru.mp4', null, '{"warmup","mobility"}', false, 42),
  ('incline_push_up', 'Отжимания от опоры', 'Incline push-up', 'Отжимания от опоры', 'Отжимания от опоры — от стула, стола или подоконника — самый мягкий вход в жимовые движения: чем выше опора, тем меньше веса приходится на руки. В отличие от отжиманий с колен, здесь ты держишь честную планку всем телом, поэтому корпус учится работать сразу. Постепенно опускай опору ниже — и ты естественно придёшь к отжиманиям от пола.', 'chest', '{"chest","triceps","shoulders","core"}', 'push_horizontal', '{"chair"}', 1, 'reps', 2.5, null, null, '{"upper","push"}', false, 43),
  ('jog_in_place', 'Бег на месте', 'Jog in place', 'Бег на месте', 'Бег на месте — самый простой способ поднять температуру тела и пульс перед тренировкой. Он мягко готовит суставы ног, икры и стопы к прыжкам и приседаниям и подходит любому уровню. Это базовый вариант для тех, кому пока тяжело бегать с высоким подниманием колен или делать джампинг-джек.', 'calves', '{"calves","quads","hip_flexors","cardio"}', 'locomotion', '{"none"}', 1, 'seconds', null, null, null, '{"cardio","warmup"}', false, 44),
  ('jump_squat', 'Приседания с выпрыгиванием', 'Jump squat', 'Присед с прыжком', 'Приседание с выпрыгиванием добавляет к обычному приседу взрывной прыжок: ты учишься быстро выдавать силу ногами и мягко приземляться. Это главный «бесплатный» способ прокачать мощность и пульс без оборудования, поэтому мы ставим его в метконы и интервалы. Ключ к безопасности — тихое приземление на всю стопу с согнутыми коленями.', 'quads', '{"quads","glutes","calves","hamstrings","cardio"}', 'jump', '{"none"}', 2, 'reps', 2, null, null, '{"lower","explosive","cardio"}', false, 45),
  ('jumping_jack', 'Джампинг-джек', 'Jumping jacks', 'Джампинг-джек', 'Джампинг-джек — прыжки с разведением ног и подъёмом рук над головой. Самое доступное кардио-упражнение: разогревает всё тело, включает плечи и икры и не требует места. Мы используем его в начале каждой разминки и как лёгкую замену скакалке, когда её нет под рукой. Один прыжок с разведением и возвратом = одно повторение.', 'calves', '{"calves","shoulders","quads","cardio"}', 'jump', '{"none"}', 1, 'reps', 1, null, null, '{"cardio","warmup"}', false, 46),
  ('jumping_lunge', 'Выпады с прыжком', 'Jumping lunge', 'Выпады с прыжком', 'Выпады с прыжком — плиометрическая версия выпада: в прыжке ты меняешь ноги и приземляешься сразу в следующий выпад. Это мощная нагрузка на ноги и сердце, которая развивает скорость, координацию и устойчивость колена. Ставим их только после того, как обычные выпады выполняются чисто и без боли.', 'quads', '{"quads","glutes","calves","hamstrings","cardio"}', 'jump', '{"none"}', 3, 'reps', 1.5, null, null, '{"lower","explosive","cardio","unilateral"}', false, 47),
  ('kb_clean', 'Взятие гири на грудь', 'Kettlebell clean', 'Взятие гири', 'Взятие гири на грудь — подъём гири с замаха между ног в положение «на груди»: гиря лежит на предплечье, локоть прижат к телу. Это мах, который заканчивается не перед собой, а на груди, поэтому сила снова идёт из таза, а рука лишь направляет гирю. Чистое взятие — тихое: гиря мягко ложится на предплечье, а не ударяет по нему. Оно открывает дорогу к жиму, выпадам с гирей у груди и рывку. Повторения указаны на каждую руку.', 'glutes', '{"glutes","hamstrings","back","biceps","shoulders","core"}', 'olympic', '{"kettlebell"}', 2, 'reps', 2, null, null, '{"explosive","unilateral","lower","upper"}', false, 48),
  ('kb_deadlift', 'Становая тяга с гирей', 'Kettlebell deadlift', 'Становая с гирей', 'Становая тяга с гирей — подъём гири с пола между стоп за счёт разгибания таза и колен с прямой спиной. Это первое упражнение, которое мы учим с гирей: оно ставит наклон таза, правильный старт и хват — всё, что потом понадобится в махах, взятии и рывке. Гиря стоит между ног, поэтому вес расположен идеально близко к телу и техника даётся легко даже новичку.', 'glutes', '{"glutes","hamstrings","back","quads","core"}', 'hinge', '{"kettlebell"}', 1, 'reps', 3, null, null, '{"lower"}', false, 49),
  ('kb_goblet_squat', 'Гоблет-присед с гирей', 'Kettlebell goblet squat', 'Гоблет с гирей', 'Гоблет-присед с гирей — приседание с гирей, которую ты держишь за рога у груди. Гиря удобнее гантели: центр тяжести ближе к телу, а локти естественно уходят вниз и раздвигают колени в нижней точке. Это основное приседание гиревого курса: оно строит квадрицепсы и ягодицы и учит глубокому, вертикальному приседу с весом перед собой.', 'quads', '{"quads","glutes","core","back"}', 'squat', '{"kettlebell"}', 1, 'reps', 3, null, null, '{"lower"}', false, 50),
  ('kb_halo', 'Гало с гирей', 'Kettlebell halo', 'Гало', 'Гало — медленное обведение гири вокруг головы, держа её за рога дном вверх. Это разминка для плеч, грудного отдела и мышц вокруг лопаток: пока гиря идёт по кругу, суставы проходят полную амплитуду под небольшой нагрузкой и включаются в работу. Мы начинаем с гало почти каждую гиревую тренировку, чтобы плечи были готовы к жимам и рывкам. Половину повторений крути в одну сторону, половину — в другую.', 'shoulders', '{"shoulders","back","core","triceps"}', 'mobility', '{"kettlebell"}', 1, 'reps', 4, null, null, '{"warmup","mobility","upper"}', false, 51),
  ('kb_lunge', 'Обратные выпады с гирей у груди', 'Kettlebell front-rack reverse lunge', 'Выпады с гирей', 'Обратные выпады с гирей у груди — выпады назад с гирей, лежащей на предплечье в положении «на груди». Вес спереди и сбоку заставляет корпус держаться вертикально и не заваливаться в сторону, поэтому вместе с ногами работают пресс и косые мышцы. Это основное одностороннее упражнение гиревого курса и следующий шаг после гоблет-приседа. Повторения считаем суммарно, чередуя ноги; половину подхода гиря в одной руке, половину — в другой.', 'quads', '{"quads","glutes","hamstrings","core","obliques"}', 'lunge', '{"kettlebell"}', 2, 'reps', 3, null, null, '{"lower","unilateral","core"}', false, 52),
  ('kb_press', 'Жим гири стоя', 'Kettlebell press', 'Жим гири', 'Жим гири стоя — строгий жим одной рукой из положения «на груди» над головой. Гиря висит за кистью и тянет руку назад, поэтому плечо, трицепс и мышцы, стабилизирующие лопатку, работают сильнее, чем с гантелью того же веса, а корпус учится не наклоняться в сторону. Это базовый жим гиревого курса. Повторения указаны на каждую руку.', 'shoulders', '{"shoulders","triceps","core","obliques"}', 'push_vertical', '{"kettlebell"}', 2, 'reps', 2.5, null, null, '{"upper","push","unilateral"}', false, 53),
  ('kb_snatch', 'Рывок гири', 'Kettlebell snatch', 'Рывок гири', 'Рывок гири — мах, который заканчивается фиксацией гири над головой на прямой руке за одно движение. Это вершина гиревого курса: мощность таза, сильный хват, стабильные плечи и выносливость на высоком пульсе. Главная тонкость — «пронырнуть» кистью под гирю в верхней точке, чтобы она мягко перевернулась на предплечье, а не ударила по нему. Осваивай рывок только после чистых махов и взятия. Повторения указаны на каждую руку.', 'glutes', '{"glutes","hamstrings","back","shoulders","core","cardio"}', 'olympic', '{"kettlebell"}', 3, 'reps', 2, null, null, '{"explosive","cardio","unilateral","benchmark"}', false, 54),
  ('kb_suitcase_carry', 'Прогулка с гирей в одной руке', 'Suitcase carry', 'Прогулка с гирей', 'Прогулка с гирей в одной руке — ходьба с весом на одной стороне, как с чемоданом. Вес тянет тебя вбок, а косые мышцы и кор не дают наклониться — это лучшее упражнение на боковую стабильность корпуса и защиту поясницы в жизни. Заодно тренируются хват и осанка. Держи плечи на одной высоте и иди так, будто гири нет. Время указано на каждую сторону.', 'obliques', '{"obliques","core","back","shoulders","glutes"}', 'carry', '{"kettlebell"}', 1, 'seconds', null, null, null, '{"carry","core","unilateral"}', false, 55),
  ('kb_sumo_high_pull', 'Тяга сумо к подбородку', 'Sumo deadlift high pull', 'Тяга сумо', 'Тяга сумо к подбородку — становая тяга в широкой стойке, которая переходит в тягу гири к подбородку за счёт разгона ног и таза. Это одно из классических кроссфит-движений: за одно повторение работают ноги, ягодицы, спина, трапеции и плечи, а пульс растёт как в метконе. Ключ — локти выше кистей и разгон снизу: руки не тянут сами по себе, а лишь заканчивают движение.', 'glutes', '{"glutes","quads","hamstrings","back","shoulders","cardio"}', 'hinge', '{"kettlebell"}', 2, 'reps', 2, null, null, '{"lower","upper","explosive","cardio"}', false, 56),
  ('kb_swing', 'Махи гирей', 'Kettlebell swing', 'Махи гирей', 'Махи гирей — главное упражнение гиревого курса: взрывное разгибание таза выбрасывает гирю до уровня груди, а затем ты снова «ловишь» её между ног. Это одновременно сила задней поверхности тела, мощность и кардио, при этом колени почти не нагружаются. Мах — не присед и не подъём руками: гиря летит только за счёт таза. Мы делаем русский мах — до уровня плеч, не выше.', 'glutes', '{"glutes","hamstrings","back","core","cardio"}', 'hinge', '{"kettlebell"}', 2, 'reps', 1.6, null, null, '{"lower","explosive","cardio","benchmark"}', false, 57),
  ('kb_turkish_get_up', 'Турецкий подъём', 'Turkish get-up', 'Турецкий подъём', 'Турецкий подъём — вставание с пола с гирей, поднятой над головой на прямой руке, и такое же медленное возвращение обратно. Одно повторение занимает около полминуты и проходит через семь положений: локоть, ладонь, мост, колено, выпад, стойка — и назад. Это одновременно упражнение на стабильность плеча, кор, подвижность бёдер и внимание; ни одно другое движение не учит так хорошо владеть своим телом под нагрузкой. Начни без веса или с бутылкой воды, чтобы выучить последовательность. Повторения указаны на каждую сторону.', 'shoulders', '{"shoulders","core","obliques","glutes","full_body"}', 'full_body', '{"kettlebell"}', 3, 'reps', 30, null, null, '{"core","upper","mobility","unilateral"}', false, 58),
  ('knee_circles', 'Круги коленями', 'Knee circles', 'Круги коленями', 'Круги коленями — классика суставной гимнастики перед приседаниями и выпадами. Стопы вместе, ладони на коленях, колени рисуют небольшие круги; сустав получает движение и синовиальную жидкость до того, как на него ляжет нагрузка. Круги маленькие и мягкие — колено не любит больших кругов под весом.', 'quads', '{"quads","calves"}', 'mobility', '{"none"}', 1, 'seconds', null, 'storage:videos/shared/knee_circles.ru.mp4', null, '{"warmup","mobility","lower"}', false, 59),
  ('knee_push_up', 'Отжимания с колен', 'Knee push-up', 'Отжимания с колен', 'Отжимания с колен убирают из движения вес ног, поэтому груди и трицепсам достаётся примерно на треть меньше нагрузки, чем в классических. Техника при этом та же — прямая линия от коленей до макушки, полная амплитуда, локти под углом. Это официальный вариант нашего теста на отжимания и первая ступень к отжиманиям с носков.', 'chest', '{"chest","triceps","shoulders","core"}', 'push_horizontal', '{"none"}', 1, 'reps', 2.5, 'storage:videos/shared/knee_push_up.ru.mp4', null, '{"upper","push","benchmark"}', true, 60),
  ('lateral_lunge', 'Боковые выпады', 'Lateral lunge', 'Боковые выпады', 'Боковой выпад — шаг в сторону с приседанием на одну ногу. Он нагружает ягодицы и внутреннюю поверхность бедра, которые в обычных приседаниях почти не работают, и растягивает приводящие мышцы. Это движение в боковой плоскости готовит колени и тазобедренные суставы к прыжкам «конькобежец» и защищает от травм при резкой смене направления.', 'glutes', '{"glutes","quads","hamstrings","core"}', 'lunge', '{"none"}', 2, 'reps', 3, null, null, '{"lower","unilateral","mobility"}', false, 61),
  ('leg_raise', 'Подъём ног лёжа', 'Lying leg raise', 'Подъём ног', 'Подъём ног лёжа тренирует нижнюю часть пресса и сгибатели бедра, а главное — умение держать поясницу прижатой, когда ноги тянут её в прогиб. Это подводящее упражнение к подъёмам коленей и ног в висе. Всё решает контроль на опускании: чем медленнее ноги идут вниз, тем больше пользы.', 'core', '{"core","hip_flexors"}', 'core_flexion', '{"none"}', 2, 'reps', 3, null, null, '{"core"}', false, 62),
  ('leg_swing', 'Махи ногами', 'Leg swings', 'Махи ногами', 'Махи ногами — динамическая растяжка тазобедренного сустава перед приседаниями, выпадами и бегом. Нога свободно качается вперёд-назад, постепенно увеличивая амплитуду, а задняя поверхность бедра и сгибатели бедра разогреваются без статики. Делай на каждую ногу; в задании повторения указаны на одну сторону.', 'hip_flexors', '{"hip_flexors","hamstrings","glutes"}', 'mobility', '{"none"}', 1, 'reps', 1.5, 'storage:videos/shared/leg_swing.ru.mp4', null, '{"warmup","mobility","lower","unilateral"}', false, 63),
  ('mountain_climber', 'Скалолаз', 'Mountain climbers', 'Скалолаз', 'Скалолаз — быстрый бег коленями к груди в упоре лёжа. Он одновременно нагружает кор, плечи и сердечно-сосудистую систему, поэтому это одно из главных кардио-упражнений без оборудования. Плечи стоят над кистями, а таз не подпрыгивает — тогда работает пресс, а не поясница. Одно подтягивание колена = одно повторение (считаем суммарно на обе ноги).', 'core', '{"core","hip_flexors","shoulders","cardio"}', 'locomotion', '{"none"}', 2, 'reps', 1, 'storage:videos/shared/mountain_climber.ru.mp4', null, '{"cardio","core"}', false, 64),
  ('neck_circles', 'Круги головой', 'Neck circles', 'Круги головой', 'Круги головой открывают суставную гимнастику: шея первой получает движение, потому что она первой зажимается от телефона и стола. Медленные полукруги от плеча к плечу разогревают мелкие мышцы шеи и верх трапеции перед отжиманиями и планками, где голова должна держаться в линии с корпусом. Это подготовка, а не упражнение на силу: никаких резких движений и никаких запрокидываний назад.', 'back', '{"back","shoulders"}', 'mobility', '{"none"}', 1, 'seconds', null, 'storage:videos/shared/neck_circles.ru.mp4', null, '{"warmup","mobility","upper"}', false, 65),
  ('negative_pull_up', 'Негативные подтягивания', 'Negative pull-up', 'Негативные', 'Негативные подтягивания — это только опускание: ты запрыгиваешь или залезаешь в верхнюю точку и медленно опускаешься в вис. Мышцы сильнее на удлинении, чем на сокращении, поэтому даже без единого подтягивания ты можешь нагрузить спину и бицепсы в полной амплитуде. Это самый короткий путь к первому чистому подтягиванию. Опускайся не быстрее трёх секунд — иначе пользы почти нет.', 'lats', '{"lats","biceps","back","core"}', 'pull_vertical', '{"pullup_bar"}', 2, 'reps', 5, null, null, '{"upper","pull"}', false, 66),
  ('pike_push_up', 'Отжимания уголком', 'Pike push-up', 'Отжимания уголком', 'Отжимания уголком — это жим вверх без оборудования: ты поднимаешь таз, ставишь тело «домиком» и отжимаешься так, что нагрузка ложится на плечи и трицепсы. Это домашняя замена жиму стоя и первая ступень к отжиманиям в стойке на руках. Чем ближе стопы к ладоням и выше таз, тем больше нагрузка на плечи.', 'shoulders', '{"shoulders","triceps","chest","core"}', 'push_vertical', '{"none"}', 2, 'reps', 3, null, null, '{"upper","push"}', false, 67),
  ('plank', 'Планка', 'Plank', 'Планка', 'Планка — базовое статическое упражнение на мышцы кора: ты удерживаешь тело в прямой линии на предплечьях и носках, а пресс, ягодицы и спина не дают пояснице провиснуть. Именно это умение «держать корпус» нужно в приседаниях, отжиманиях и любом движении с гантелями. В тесте мы засекаем максимальное время удержания — простой и честный показатель выносливости кора.', 'core', '{"core","shoulders","glutes"}', 'core_anti_extension', '{"none"}', 1, 'seconds', null, null, null, '{"core","benchmark"}', true, 68),
  ('plank_shoulder_tap', 'Касания плеч в планке', 'Plank shoulder taps', 'Касания плеч', 'Касания плеч в планке — это планка на прямых руках, в которой ты по очереди отрываешь ладони от пола и касаешься противоположного плеча. Каждый раз, когда одна рука уходит, корпус должен удержать таз от раскачивания — так тренируется анти-ротационная сила пресса и стабильность плеч. Считаем каждое касание за одно повторение.', 'core', '{"core","obliques","shoulders"}', 'core_anti_extension', '{"none"}', 2, 'reps', 1.5, null, null, '{"core","upper"}', false, 69),
  ('pull_up', 'Подтягивания', 'Pull-up', 'Подтягивания', 'Подтягивания — главная вертикальная тяга в домашнем тренинге и лучший тест силы спины и хвата. Они строят широчайшие, бицепсы и мышцы между лопатками, которые в отжиманиях и жимах не работают, и уравновешивают всю жимовую нагрузку программы. Мы считаем строгие подтягивания: без раскачки, из полного виса до подбородка над перекладиной. Если чистых повторений пока нет — начни с негативных подтягиваний и виса.', 'lats', '{"lats","biceps","back","core"}', 'pull_vertical', '{"pullup_bar"}', 3, 'reps', 3, null, null, '{"upper","pull","benchmark"}', false, 70),
  ('push_up', 'Отжимания', 'Push-up', 'Отжимания', 'Отжимания — главный жим в домашнем тренинге: они развивают грудные мышцы, трицепсы и переднюю часть плеч, а ещё держат всё тело в напряжённой планке. Именно поэтому мы используем максимальное число отжиманий как тест силы верха тела — оно входит в расчёт твоего фитнес-индекса. Если чистых отжиманий пока мало, начни с колен или от опоры — прогресс здесь очень заметен.', 'chest', '{"chest","triceps","shoulders","core"}', 'push_horizontal', '{"none"}', 2, 'reps', 2.5, 'storage:videos/shared/push_up.ru.mp4', null, '{"upper","push","benchmark"}', true, 71),
  ('quad_stretch', 'Растяжка передней поверхности бедра', 'Standing quad stretch', 'Растяжка бедра', 'Растяжка передней поверхности бедра стоя — заминка после приседаний, выпадов, зашагиваний и бёрпи. Пятка подтягивается к ягодице, колени вместе, таз чуть подан вперёд — тянется квадрицепс и передняя часть бедра. Держи стену или стул для равновесия; в задании время указано на одну ногу.', 'quads', '{"quads","hip_flexors"}', 'mobility', '{"none"}', 1, 'seconds', null, 'storage:videos/shared/quad_stretch.ru.mp4', null, '{"cooldown","mobility","lower"}', false, 72),
  ('reverse_lunge', 'Обратные выпады', 'Reverse lunge', 'Обратные выпады', 'Обратный выпад — самый безопасный вариант выпада: шаг назад, а не вперёд, снимает лишнюю нагрузку с колена передней ноги и легче контролируется. Он прорабатывает квадрицепсы и ягодицы каждой ноги отдельно, тренирует баланс и подвижность бёдер. Повторения считаем суммарно на обе ноги, чередуя стороны.', 'quads', '{"quads","glutes","hamstrings","core"}', 'lunge', '{"none"}', 1, 'reps', 2.5, 'storage:videos/shared/reverse_lunge.ru.mp4', null, '{"lower","unilateral"}', false, 73),
  ('russian_twist', 'Русский твист', 'Russian twist', 'Русский твист', 'Русский твист — повороты корпуса из положения сидя с приподнятыми ногами. Это упражнение на косые мышцы живота и вращательную силу — то, чего не дают планки и ситапы. В программе оно закрывает паттерн «ротация» без оборудования; при желании держи в руках гантель или бутылку с водой. Одно касание пола = одно повторение.', 'obliques', '{"obliques","core","hip_flexors"}', 'core_rotation', '{"none"}', 2, 'reps', 1.5, 'storage:videos/shared/russian_twist.ru.mp4', null, '{"core"}', false, 74),
  ('side_bend', 'Наклоны корпуса в стороны', 'Side bends', 'Наклоны в стороны', 'Наклоны в стороны разминают позвоночник и косые мышцы живота — то, что держит корпус в ситапах, русском твисте и планках. Ноги на ширине плеч, одна рука тянется через голову, корпус наклоняется от талии, таз остаётся на месте. Это мягкое движение, а не растяжка до предела: амплитуда растёт от повтора к повтору.', 'obliques', '{"obliques","core","back"}', 'mobility', '{"none"}', 1, 'seconds', null, 'storage:videos/shared/side_bend.ru.mp4', null, '{"warmup","mobility","core"}', false, 75),
  ('side_plank', 'Боковая планка', 'Side plank', 'Боковая планка', 'Боковая планка нагружает косые мышцы живота и боковую стабильность корпуса — то, что обычная планка почти не трогает. Она укрепляет мышцы, которые не дают тазу и пояснице «уезжать» в сторону при выпадах, беге и переносе веса в одной руке. Делается на каждую сторону — время в задании указано на одну сторону.', 'obliques', '{"obliques","core","shoulders","glutes"}', 'core_anti_extension', '{"none"}', 2, 'seconds', null, null, null, '{"core","unilateral"}', false, 76),
  ('single_leg_glute_bridge', 'Ягодичный мостик на одной ноге', 'Single-leg glute bridge', 'Мостик на одной', 'Мостик на одной ноге удваивает нагрузку на рабочую ягодицу и заставляет корпус удерживать таз ровно. Так ты находишь и подтягиваешь слабую сторону — асимметрия ног обычно проявляется именно здесь. Упражнение готовит к румынской тяге на одной ноге и к бегу, где каждая нога работает по очереди.', 'glutes', '{"glutes","hamstrings","core"}', 'hinge', '{"none"}', 2, 'reps', 2.5, null, null, '{"lower","unilateral"}', false, 77),
  ('single_leg_rdl', 'Румынская тяга на одной ноге', 'Single-leg Romanian deadlift', 'Тяга на одной ноге', 'Румынская тяга на одной ноге — наклон вперёд с опорой на одну ногу, при котором свободная нога уходит назад противовесом. Это лучшее упражнение без оборудования для задней поверхности бедра и ягодиц, а заодно тренировка баланса, стоп и мышц-стабилизаторов таза. Освоив его, ты легко перейдёшь к тягам с гантелями.', 'hamstrings', '{"hamstrings","glutes","core","back"}', 'hinge', '{"none"}', 2, 'reps', 3.5, null, null, '{"lower","unilateral"}', false, 78),
  ('single_under', 'Прыжки на скакалке', 'Single-unders', 'Скакалка', 'Прыжки на скакалке — один оборот троса на один прыжок. Это самое эффективное домашнее кардио: за минуту скакалка сжигает больше, чем бег в среднем темпе, и заодно тренирует икры, стопы, координацию и ритм. Мы используем её в разминке и как «дыхательный» элемент в метконах. Прыгай низко, приземляйся мягко, крути скакалку кистями, а не всей рукой.', 'calves', '{"calves","quads","shoulders","cardio"}', 'jump', '{"jump_rope"}', 1, 'reps', 0.6, null, null, '{"cardio","warmup"}', false, 79),
  ('sit_up', 'Ситап', 'Sit-up', 'Ситап', 'Ситап — классическое динамическое упражнение на пресс: из положения лёжа ты поднимаешься в сед и возвращаешься назад. В отличие от короткого скручивания здесь работают и прямая мышца живота, и сгибатели бедра в полной амплитуде, поэтому ситапы — стандарт в кроссфит-комплексах. Делай их плавно и без рывков — так спина остаётся в безопасности, а пресс получает всю нагрузку.', 'core', '{"core","hip_flexors"}', 'core_flexion', '{"none"}', 1, 'reps', 2.5, 'storage:videos/shared/sit_up.ru.mp4', null, '{"core"}', false, 80),
  ('skater', 'Конькобежец', 'Skater jumps', 'Конькобежец', 'Конькобежец — боковые прыжки с ноги на ногу, как у скоростного конькобежца. Упражнение развивает взрывную силу ног, стабильность колена и голеностопа и мышцы, которые работают во фронтальной плоскости, — их обычные приседания и выпады почти не трогают. Это отличная кардио-нагрузка без ударов на позвоночник. Каждый прыжок = одно повторение (считаем суммарно на обе стороны).', 'glutes', '{"glutes","quads","calves","hamstrings","cardio"}', 'jump', '{"none"}', 2, 'reps', 1.2, null, null, '{"cardio","explosive","lower","unilateral"}', false, 81),
  ('squat_hold', 'Удержание в приседе', 'Bottom squat hold', 'Глубокий присед', 'Удержание в глубоком приседе — статика в нижней точке приседания. Пока ты сидишь, раскрываются голеностопы и тазобедренные суставы, а тело запоминает правильное положение: пятки на полу, колени наружу, спина прямая. Мы ставим его в разминку перед приседаниями и выпадами, а ещё это отличный тест твоей подвижности.', 'glutes', '{"glutes","quads","hip_flexors","calves"}', 'mobility', '{"none"}', 1, 'seconds', null, null, null, '{"warmup","mobility","lower"}', false, 82),
  ('squat_to_stand', 'Присед-разгибание', 'Squat to stand', 'Присед-разгибание', 'Присед-разгибание — разминочное упражнение, которое за одно движение раскрывает тазобедренные суставы, голеностопы и заднюю поверхность бедра. Ты наклоняешься, берёшься за носки, «садишься» в глубокий присед с прямой спиной и затем разгибаешь ноги, не отпуская стопы. Несколько повторений перед тренировкой — и приседания получаются глубже и увереннее.', 'hamstrings', '{"hamstrings","glutes","quads","back"}', 'mobility', '{"none"}', 1, 'reps', 5, 'storage:videos/shared/squat_to_stand.ru.mp4', null, '{"warmup","mobility","lower"}', false, 83),
  ('step_up', 'Зашагивания на возвышение', 'Step-up', 'Зашагивания', 'Зашагивание — подъём на устойчивый стул, ступеньку или бокс одной ногой. Это простое и очень «честное» упражнение: рабочая нога поднимает всё тело сама, без помощи толчка снизу, поэтому ягодицы и квадрицепсы получают хорошую нагрузку при минимальном стрессе для суставов. Высота опоры регулирует сложность — начни с высоты, при которой колено согнуто не больше чем под прямым углом.', 'quads', '{"quads","glutes","hamstrings","calves"}', 'lunge', '{"chair","box"}', 1, 'reps', 3, 'storage:videos/shared/step_up.ru.mp4', null, '{"lower","unilateral"}', false, 84),
  ('superman', 'Супермен', 'Superman', 'Супермен', 'Супермен — подъём рук и ног лёжа на животе. Он укрепляет разгибатели спины, ягодицы и заднюю поверхность плеч — мышцы, которые держат осанку и защищают поясницу в тягах и наклонах. Мы ставим его в разминку и в блоки на кор как противовес планкам и скручиваниям: спина должна быть такой же сильной, как пресс.', 'back', '{"back","glutes","hamstrings","shoulders"}', 'core_anti_extension', '{"none"}', 1, 'reps', 3, null, null, '{"core","warmup"}', false, 85),
  ('tuck_jump', 'Прыжок с подтягиванием коленей', 'Tuck jump', 'Колени к груди', 'Прыжок с подтягиванием коленей — вертикальный прыжок, в котором ты подтягиваешь колени к груди в верхней точке. Это самое интенсивное плиометрическое упражнение без оборудования: ноги, пресс и сердце работают на пределе. Ставим его коротко и только к концу интервального блока, когда техника мягкого приземления уже надёжна.', 'quads', '{"quads","glutes","calves","hip_flexors","core","cardio"}', 'jump', '{"none"}', 3, 'reps', 1.5, null, null, '{"lower","explosive","cardio"}', false, 86),
  ('up_down_plank', 'Планка вверх-вниз', 'Up-down plank', 'Планка вверх-вниз', 'Планка вверх-вниз — переход из планки на локтях в планку на прямых руках и обратно, по одной руке за раз. Это одновременно упражнение на пресс, плечи и трицепсы и неплохой разгон пульса, поэтому оно часто стоит в круговых блоках. Главное правило — таз и плечи не крутятся, пока руки меняют положение. Одно повторение — подъём и опускание.', 'core', '{"core","shoulders","triceps","chest"}', 'push_horizontal', '{"none"}', 2, 'reps', 4, null, null, '{"core","upper","cardio"}', false, 87),
  ('v_up', 'Складка', 'V-up', 'Складка', 'Складка — продвинутый вариант ситапа: ты одновременно поднимаешь прямые ноги и корпус, складываясь в букву V, и касаешься руками стоп. Это одно из самых сильных упражнений на пресс без оборудования: работает весь корпус, сгибатели бедра и координация. Требует хорошей «лодочки» и умения держать поясницу — если это пока не про тебя, делай ситапы.', 'core', '{"core","hip_flexors","quads"}', 'core_flexion', '{"none"}', 3, 'reps', 2.5, null, null, '{"core","explosive"}', false, 88),
  ('wall_sit', 'Стульчик у стены', 'Wall sit', 'Стульчик', 'Стульчик — статическое удержание приседа спиной к стене. Пока ты сидишь, квадрицепсы и ягодицы работают без движения в суставах, поэтому упражнение подходит даже тем, кому больно приседать. Оно тренирует терпение и силовую выносливость ног, а ещё учит держать колени под прямым углом — как в нижней точке приседа.', 'quads', '{"quads","glutes","core"}', 'squat', '{"none"}', 1, 'seconds', null, null, null, '{"lower"}', false, 89),
  ('worlds_greatest_stretch', 'Выпад с ротацией', 'World''s greatest stretch', 'Выпад с ротацией', 'Выпад с ротацией — «лучшая растяжка в мире», как её называют в кроссфите: одно движение раскрывает тазобедренные суставы, грудной отдел, заднюю поверхность бедра и плечи. Это идеальная разминка перед приседаниями, тягами и любой тренировкой на всё тело. Делай на каждую сторону; повторения в задании указаны на одну сторону.', 'hip_flexors', '{"hip_flexors","hamstrings","glutes","back","shoulders"}', 'mobility', '{"none"}', 1, 'reps', 8, null, null, '{"warmup","mobility","unilateral"}', false, 90)
on conflict (id) do update set
  name_ru = excluded.name_ru,
  name_en = excluded.name_en,
  short_name_ru = excluded.short_name_ru,
  description_ru = excluded.description_ru,
  primary_muscle = excluded.primary_muscle,
  muscles = excluded.muscles,
  pattern = excluded.pattern,
  equipment = excluded.equipment,
  level = excluded.level,
  unit = excluded.unit,
  seconds_per_rep = excluded.seconds_per_rep,
  is_test = excluded.is_test,
  sort_order = excluded.sort_order,
  updated_at = now()
-- An exercise written in the admin panel is not owned by these files. If its id ever collides with
-- a generated one, the hand-written row wins and the re-seed leaves it alone (0008).
where public.exercises.is_custom = false;

-- =============================================================================
-- 0008_course_builder.sql — Courses the coach builds in the admin panel.
-- =============================================================================

-- =============================================================================
-- 0008 — Courses the coach builds in the admin panel.
--
-- Until now a course was a TypeScript file in content/courses/, compiled into the static build;
-- public.courses held nothing but an allowlist of ids. That makes a course impossible to author
-- without a code change, which is the thing the admin panel most needs to do.
--
-- Two tables:
--   admin_courses      one row per course — the catalogue fields the app and the landing page
--                      query on as columns, and the prose (names, descriptions, FAQ) as one
--                      jsonb `content` blob, because the editor writes it as a whole and nothing
--                      filters on it.
--   admin_course_days  the days of a course, in order: week + day, a kind (workout / rest / test /
--                      benchmark / milestone), its own title and body text, an optional image, and
--                      for the training days a reference to a custom_workouts row. That reference
--                      is what makes the workout library from 0006 reusable: a workout is built
--                      once and dropped into as many days and courses as it belongs in.
--
-- Publishing is an explicit step (admin_publish_course). A draft is visible only to admins; only
-- publishing writes the course id into public.courses and its workouts' base_points into
-- public.workouts, which is what entitlements and session scoring key off. That keeps a half-built
-- course from being purchasable or playable.
--
-- Requires 0001_init.sql (courses, workouts, is_admin, current_email, has_entitlement,
-- set_updated_at) and 0006_custom_workouts.sql (exercises, custom_workouts).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- admin_courses
-- -----------------------------------------------------------------------------
create table if not exists public.admin_courses (
  id            uuid primary key default gen_random_uuid(),
  -- The course id used everywhere else: purchases.course_id, workout_sessions.course_id,
  -- user_course_state.course_id, the videos bucket's first path segment. Same format as
  -- public.courses.id, and fixed once the course has been published (enforced below).
  slug_id       text not null unique check (slug_id ~ '^[a-z0-9_]{2,40}$'),
  status        text not null default 'draft' check (status in ('draft', 'published', 'archived')),
  sort_order    int not null default 0,

  -- Catalogue fields. Columns rather than jsonb because the app filters and sorts on them and the
  -- landing-page generator needs them without parsing a blob.
  level             int not null default 1 check (level between 1 and 3),
  weeks             int not null default 4 check (weeks between 1 and 16),
  sessions_per_week int not null default 3 check (sessions_per_week between 1 and 7),
  avg_session_min   int not null default 30 check (avg_session_min between 5 and 120),
  equipment         text[] not null default '{none}',
  -- One flat tile colour from --tile-1…5 (src/styles/global.css); see CourseSchema.tile.
  tile              text not null default '#1A2634' check (tile ~ '^#[0-9a-fA-F]{6}$'),
  price_rub         numeric(10, 2) not null default 0 check (price_rub >= 0),
  price_usd         numeric(10, 2) not null default 0 check (price_usd >= 0),

  /*
   * content — every piece of prose, in the shape CourseSchema expects (src/content/schema.ts):
   *   { slug: {ru,en}, name: {ru,en}, tagline: {ru,en}, description: {ru,en},
   *     longDescription: [{ru,en}], forWhom: [{ru,en}], outcomes: [{ru,en}],
   *     faq: [{q:{ru,en}, a:{ru,en}}],
   *     coverImage?: string, introVideo?: {ru?,en?}, paymentUrl?: {ru?,en?} }
   * Validated by zod in the client before every write; the check below only bounds its size.
   */
  content       jsonb not null default '{}'::jsonb,

  author_id     uuid references auth.users (id) on delete set null,
  published_at  timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

comment on table public.admin_courses is
  'Courses authored in the admin panel. Publishing copies slug_id into public.courses and the days'' workout base_points into public.workouts.';

-- A course's prose runs to a few KB; 256 KB is far more than any of the five existing courses
-- needs and stops a client from parking blobs here.
alter table public.admin_courses drop constraint if exists admin_courses_content_len;
alter table public.admin_courses add constraint admin_courses_content_len
  check (octet_length(content::text) <= 262144) not valid;

create index if not exists admin_courses_status_idx on public.admin_courses (status, sort_order);

drop trigger if exists admin_courses_touch on public.admin_courses;
create trigger admin_courses_touch
  before update on public.admin_courses
  for each row execute function public.set_updated_at();

-- slug_id is the key every purchase, session and storage path is written against, so once a course
-- has been published it can never be renamed — that would orphan the history silently.
create or replace function public.admin_courses_freeze_slug()
returns trigger
language plpgsql
set search_path = pg_catalog, public, extensions
as $$
begin
  if old.published_at is not null and new.slug_id is distinct from old.slug_id then
    raise exception 'slug_id is fixed once a course has been published'
      using errcode = 'P0001', hint = 'create a new course instead of renaming this one';
  end if;
  return new;
end;
$$;

drop trigger if exists admin_courses_freeze_slug on public.admin_courses;
create trigger admin_courses_freeze_slug
  before update on public.admin_courses
  for each row execute function public.admin_courses_freeze_slug();

alter table public.admin_courses enable row level security;

-- Admins do everything. Everyone signed in may read a *published* course: the catalogue screen
-- lists courses that are not owned yet, exactly as it does for the compiled ones.
drop policy if exists "admin_courses: admins all" on public.admin_courses;
create policy "admin_courses: admins all"
  on public.admin_courses for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

drop policy if exists "admin_courses: read published" on public.admin_courses;
create policy "admin_courses: read published"
  on public.admin_courses for select
  to authenticated
  using (status = 'published');

revoke all on public.admin_courses from anon, authenticated;
grant select, insert, update, delete on public.admin_courses to authenticated;

-- -----------------------------------------------------------------------------
-- admin_course_days
-- -----------------------------------------------------------------------------
create table if not exists public.admin_course_days (
  id            uuid primary key default gen_random_uuid(),
  course_id     uuid not null references public.admin_courses (id) on delete cascade,
  -- The node id written into workout_sessions.node_id and user_course_state; same format rule.
  node_id       text not null check (node_id ~ '^[a-z0-9_]{2,40}$'),
  week          int not null check (week between 1 and 16),
  day           int not null check (day between 1 and 7),
  kind          text not null check (kind in ('workout', 'rest', 'test', 'benchmark', 'milestone')),

  -- The workout this day plays. Required for workout/test/benchmark (enforced below); null for a
  -- rest day or a milestone. `restrict` on purpose: deleting a workout that a course day still
  -- points at would silently empty that day.
  custom_workout_id uuid references public.custom_workouts (id) on delete restrict,

  /*
   * content — the day's own words, in the shape CourseNodeSchema expects plus a body:
   *   { title: {ru,en}, subtitle?: {ru,en}, body?: [{ru,en}], image?: string }
   * `body` is the paragraphs shown on the day's preview screen — what a yoga course needs and a
   * strength course rarely uses.
   */
  content       jsonb not null default '{}'::jsonb,

  deload        boolean not null default false,
  steps_goal    int check (steps_goal is null or steps_goal between 1000 and 50000),
  sort_order    int not null default 0,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),

  unique (course_id, node_id),
  -- One day per calendar slot: the path screen lays days out on a week/day grid.
  unique (course_id, week, day)
);

comment on table public.admin_course_days is
  'The days of an admin-authored course, in order. Training days point at a custom_workouts row.';

alter table public.admin_course_days drop constraint if exists admin_course_days_content_len;
alter table public.admin_course_days add constraint admin_course_days_content_len
  check (octet_length(content::text) <= 65536) not valid;

-- A day that plays a workout must have one; a rest day or milestone must not carry a stale
-- reference to one.
alter table public.admin_course_days drop constraint if exists admin_course_days_workout_required;
alter table public.admin_course_days add constraint admin_course_days_workout_required
  check (
    case
      when kind in ('workout', 'test', 'benchmark') then custom_workout_id is not null
      else custom_workout_id is null
    end
  );

create index if not exists admin_course_days_course_idx
  on public.admin_course_days (course_id, sort_order);
create index if not exists admin_course_days_workout_idx
  on public.admin_course_days (custom_workout_id);

drop trigger if exists admin_course_days_touch on public.admin_course_days;
create trigger admin_course_days_touch
  before update on public.admin_course_days
  for each row execute function public.set_updated_at();

alter table public.admin_course_days enable row level security;

drop policy if exists "admin_course_days: admins all" on public.admin_course_days;
create policy "admin_course_days: admins all"
  on public.admin_course_days for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- The days of a published course are readable by anyone signed in — the path screen shows the
-- shape of a course before it is bought, same as the compiled courses.
drop policy if exists "admin_course_days: read published" on public.admin_course_days;
create policy "admin_course_days: read published"
  on public.admin_course_days for select
  to authenticated
  using (
    exists (
      select 1 from public.admin_courses c
      where c.id = admin_course_days.course_id and c.status = 'published'
    )
  );

revoke all on public.admin_course_days from anon, authenticated;
grant select, insert, update, delete on public.admin_course_days to authenticated;

-- -----------------------------------------------------------------------------
-- custom_workouts: let a workout be read when it belongs to a published course.
--
-- 0006 gave three ways to reach a custom workout: you are an admin, it was assigned to you, or you
-- hold its share link. A workout that is a day of a course you have bought is a fourth, and the
-- entitlement check is the same one the compiled courses use.
-- -----------------------------------------------------------------------------
drop policy if exists "custom_workouts: read course days" on public.custom_workouts;
create policy "custom_workouts: read course days"
  on public.custom_workouts for select
  to authenticated
  using (
    exists (
      select 1
      from public.admin_course_days d
      join public.admin_courses c on c.id = d.course_id
      where d.custom_workout_id = custom_workouts.id
        and c.status = 'published'
        and public.has_entitlement(c.slug_id)
    )
  );

-- -----------------------------------------------------------------------------
-- images — a public bucket for course covers, day pictures and exercise stills.
--
-- Public, unlike `videos`: these are marketing and teaching images that the landing pages must be
-- able to render without a signed URL, and an <img> in a static page cannot mint one. The videos
-- bucket stays private — the paid content is the video.
--
-- Object naming convention:
--   images/courses/<course_id>/<file>     course cover, day pictures
--   images/exercises/<exercise_id>/<file> exercise stills
-- -----------------------------------------------------------------------------
insert into storage.buckets (id, name, public)
values ('images', 'images', true)
on conflict (id) do nothing;

-- Read: everyone, including anonymous visitors on the landing pages.
drop policy if exists "images: public select" on storage.objects;
create policy "images: public select"
  on storage.objects for select
  to anon, authenticated
  using (bucket_id = 'images');

drop policy if exists "images: admin insert" on storage.objects;
create policy "images: admin insert"
  on storage.objects for insert
  to authenticated
  with check (bucket_id = 'images' and public.is_admin());

drop policy if exists "images: admin update" on storage.objects;
create policy "images: admin update"
  on storage.objects for update
  to authenticated
  using (bucket_id = 'images' and public.is_admin())
  with check (bucket_id = 'images' and public.is_admin());

drop policy if exists "images: admin delete" on storage.objects;
create policy "images: admin delete"
  on storage.objects for delete
  to authenticated
  using (bucket_id = 'images' and public.is_admin());

-- -----------------------------------------------------------------------------
-- admin_publish_course — make a draft real.
--
-- Validates the course is complete enough to sell, then writes the two rows the rest of the
-- database keys off: public.courses (the id allowlist that public.workouts references) and
-- public.workouts (base_points per workout, read by the session scoring trigger in 0001). Both
-- are declared "written only by migrations" for clients; this function is the one exception, and
-- it is security definer precisely so the tables keep having no write policy.
-- -----------------------------------------------------------------------------
create or replace function public.admin_publish_course(p_course uuid)
returns void
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_slug  text;
  v_days  int;
  v_bad   int;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  select slug_id into v_slug from public.admin_courses where id = p_course;
  if v_slug is null then
    raise exception 'course_not_found' using errcode = 'P0001';
  end if;

  -- CourseSchema requires at least four nodes; refuse to publish anything thinner.
  select count(*) into v_days from public.admin_course_days where course_id = p_course;
  if v_days < 4 then
    raise exception 'course_too_short' using errcode = 'P0001',
      hint = 'a course needs at least 4 days';
  end if;

  -- Every training day must have a workout with at least one exercise in it.
  select count(*) into v_bad
  from public.admin_course_days d
  left join public.custom_workouts w on w.id = d.custom_workout_id
  where d.course_id = p_course
    and d.kind in ('workout', 'test', 'benchmark')
    and (
      w.id is null
      or w.is_archived
      or coalesce(jsonb_array_length(w.structure -> 'sections'), 0) = 0
    );
  if v_bad > 0 then
    raise exception 'course_has_empty_days' using errcode = 'P0001',
      hint = 'every workout day needs a workout with at least one section';
  end if;

  insert into public.courses (id, sort_order)
  values (v_slug, (select sort_order from public.admin_courses where id = p_course))
  on conflict (id) do update set sort_order = excluded.sort_order;

  -- base_points per workout. custom_workouts.points is the coach's own estimate; the content
  -- model floors basePoints at 60 and caps it at 250, so clamp into that range rather than
  -- letting an unset value fall through to the trigger's own fallback.
  -- `distinct` matters: one workout may be used by several days of the course, and an
  -- `on conflict do update` cannot touch the same row twice in a single statement.
  insert into public.workouts (course_id, id, base_points)
  select distinct v_slug, w.short_id, greatest(60, least(250, coalesce(w.points, 100)))
  from public.admin_course_days d
  join public.custom_workouts w on w.id = d.custom_workout_id
  where d.course_id = p_course
  on conflict (course_id, id) do update set base_points = excluded.base_points;

  update public.admin_courses
  set status = 'published',
      published_at = coalesce(published_at, now())
  where id = p_course;
end;
$$;

revoke execute on function public.admin_publish_course(uuid) from public, anon;
grant execute on function public.admin_publish_course(uuid) to authenticated;

-- -----------------------------------------------------------------------------
-- admin_unpublish_course — take a course off sale without destroying anything.
--
-- The public.courses and public.workouts rows stay: people who already bought the course keep
-- their entitlement, their history and their scoring. Only the catalogue listing goes away.
-- -----------------------------------------------------------------------------
create or replace function public.admin_unpublish_course(p_course uuid)
returns void
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  update public.admin_courses set status = 'draft' where id = p_course;
end;
$$;

revoke execute on function public.admin_unpublish_course(uuid) from public, anon;
grant execute on function public.admin_unpublish_course(uuid) to authenticated;

-- =============================================================================
-- 0010_public_course_pages.sql — let the static site read a published course, so it can have a page.
-- =============================================================================

-- =============================================================================
-- 0010 — let the static site read a published course, so it can have a page.
--
-- A course built in the admin panel is playable in the app the moment it is published, but it had
-- nowhere to be *sold* from: the landing pages are static HTML generated at build time from
-- content/courses/*.ts, and the build has no session, so RLS showed it nothing.
--
-- What becomes readable without signing in is exactly what a sales page shows and no more:
--
--   admin_courses      of a published course — its name, description, who it is for, the outcomes,
--                      level, length, price, FAQ. This is marketing copy; it is meant to be read by
--                      someone deciding whether to buy.
--   admin_course_days  of a published course — week, day, kind and title. The shape of the
--                      programme, which the course page already shows for the compiled courses.
--
-- What stays private is the part people pay for: `custom_workouts` is untouched here, so the
-- exercises, reps and timings of a course are still readable only by an admin, by someone the
-- workout was assigned to, or by someone holding an entitlement to the course (0008).
--
-- Requires 0008_course_builder.sql.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- admin_courses — published rows, readable by anyone.
--
-- A separate policy rather than a widening of "admin_courses: read published", because the two say
-- different things: that one lets a signed-in customer see the catalogue, this one lets an
-- anonymous visitor — and a build with no session at all — see a sales page. Postgres ORs policies
-- together, so a draft stays admin-only either way.
-- -----------------------------------------------------------------------------
drop policy if exists "admin_courses: anon reads published" on public.admin_courses;
create policy "admin_courses: anon reads published"
  on public.admin_courses for select
  to anon
  using (status = 'published');

grant select on public.admin_courses to anon;

-- -----------------------------------------------------------------------------
-- admin_course_days — the days of a published course.
-- -----------------------------------------------------------------------------
drop policy if exists "admin_course_days: anon reads published" on public.admin_course_days;
create policy "admin_course_days: anon reads published"
  on public.admin_course_days for select
  to anon
  using (
    exists (
      select 1 from public.admin_courses c
      where c.id = admin_course_days.course_id and c.status = 'published'
    )
  );

grant select on public.admin_course_days to anon;

-- -----------------------------------------------------------------------------
-- No grant on custom_workouts to anon, deliberately.
--
-- Spelled out because the omission is the security boundary and an omission is easy to "fix" by
-- accident: a course's workouts are the product. The course page shows the programme's shape from
-- the days above, and its sample workout only for the courses that live in content files, where
-- the sample was chosen by hand.
-- -----------------------------------------------------------------------------

-- =============================================================================
-- 0011_marathon.sql — Marathons: the second format.
-- =============================================================================

-- =============================================================================
-- 0011 — Marathons: the second format.
--
-- A course is a programme you walk at your own pace. A marathon is a *game played on a calendar*:
-- every day the coach sets tasks, you do them and send proof, and on Sunday night the week's
-- leaderboard decides who gets an hour with him. The two formats share almost nothing — a course
-- day is authored once and replayed by everyone whenever they reach it, a marathon day happens to
-- everyone at the same time and only once — so this is its own set of tables rather than a flag on
-- the course builder.
--
-- The shape, smallest to largest:
--
--   marathon              a run: when it starts, how many days, how big a team is
--   marathon_teams        the pairs (a marathon may have none — then everyone plays solo)
--   marathon_members      who is in, keyed on email like purchases, so the coach can add someone
--                         before they have ever opened the app
--   marathon_tasks        one row per task per day — this is the thing he creates every morning
--   marathon_submissions  one row per (task, member): the proof
--   marathon_adjustments  the coach's manual ±points, with a reason
--
-- Four decisions this schema encodes, because they are the ones that shaped it:
--
--   1. Points are computed, never stored. `marathon_scores` derives the board from submissions and
--      adjustments every time it is called. That is what makes voiding a fake proof, moving someone
--      between teams or fixing a task's points *correct the history* instead of leaving a stale
--      balance behind. Marathons are small — tens of people, tens of days — so the cost is nothing.
--   2. Proof is trusted on arrival. A submission counts the moment it is sent; the coach can void
--      it afterwards with a reason. The alternative — approve-then-count — needs someone to clear a
--      queue every single evening or the board is simply wrong, and a daily format cannot depend on
--      that.
--   3. The coach forms the teams. Membership and pairing are admin writes; nothing in the app
--      creates or joins a team.
--   4. The week is the race. Day 1..7 is week 1, 8..14 week 2, counted from the marathon's own
--      start rather than from Monday, so a marathon can begin on any weekday and every week is a
--      full seven days. `marathon_scores` takes a week and defaults to the current one.
--
-- A member never reads another member's row directly: `marathon_members` carries an email, and
-- nothing in the app needs it. Members go through `marathon_roster()` (security definer, names
-- only). The same reasoning as purchases, where a customer has no select at all.
--
-- Requires 0001_init.sql (profiles, is_admin, current_email, set_updated_at).
-- =============================================================================

-- The leaderboard and the roster join profiles on email; profiles had no index on it.
create index if not exists profiles_email_idx on public.profiles (email);

-- -----------------------------------------------------------------------------
-- marathons
-- -----------------------------------------------------------------------------
create table if not exists public.marathons (
  id          uuid primary key default gen_random_uuid(),
  -- Stable handle for links and for the app's route; same format rule as a course id.
  slug        text not null unique check (slug ~ '^[a-z0-9_]{2,40}$'),
  title       text not null check (length(title) between 1 and 120),
  description text check (description is null or length(description) <= 2000),

  -- draft    being built; invisible to members
  -- active   running; members see today's tasks
  -- finished over; the board stays readable, nothing new can be submitted
  -- archived hidden from the admin list
  status      text not null default 'draft'
              check (status in ('draft', 'active', 'finished', 'archived')),

  starts_on   date not null,
  -- Length in days. 100 is far past anything a daily-proof format survives; it is a guard rail,
  -- not a target.
  days        int not null default 28 check (days between 1 and 100),
  -- 2 is Sergey's format (a pair, both must deliver); 1 makes every member their own entry.
  team_size   int not null default 2 check (team_size between 1 and 6),

  /*
   * The marathon's clock. A day ends at `due_time` *here*, not in the athlete's phone: the whole
   * point of a shared deadline is that it is the same instant for everyone, and the coach is the
   * one who decides when the day closes.
   */
  timezone    text not null default 'Europe/Moscow' check (length(timezone) between 3 and 64),
  due_time    time not null default '22:00',

  -- The prize, as words. Shown on top of the board; the coach may run a marathon without one.
  prize       text check (prize is null or length(prize) <= 200),

  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

comment on table public.marathons is
  'A marathon: daily tasks, proof, weekly leaderboard. Points are derived by marathon_scores(), never stored.';

-- A timezone the server cannot resolve would make every deadline in the marathon wrong, and the
-- error would surface days later in the scores. Reject it at write time instead.
create or replace function public.marathons_check_timezone()
returns trigger
language plpgsql
set search_path = pg_catalog, public, extensions
as $$
begin
  if not exists (select 1 from pg_timezone_names where name = new.timezone) then
    raise exception 'unknown_timezone'
      using errcode = 'P0001', hint = 'use an IANA name such as Europe/Moscow';
  end if;
  return new;
end;
$$;

drop trigger if exists marathons_check_timezone on public.marathons;
create trigger marathons_check_timezone
  before insert or update of timezone on public.marathons
  for each row execute function public.marathons_check_timezone();

create index if not exists marathons_status_idx on public.marathons (status, starts_on desc);

drop trigger if exists marathons_touch on public.marathons;
create trigger marathons_touch
  before update on public.marathons
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- marathon_teams
-- -----------------------------------------------------------------------------
create table if not exists public.marathon_teams (
  id          uuid primary key default gen_random_uuid(),
  marathon_id uuid not null references public.marathons (id) on delete cascade,
  name        text not null check (length(name) between 1 and 60),
  sort_order  int not null default 0,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (marathon_id, name)
);

comment on table public.marathon_teams is 'Teams inside one marathon. The coach forms them; nothing in the app does.';

create index if not exists marathon_teams_marathon_idx on public.marathon_teams (marathon_id, sort_order);

drop trigger if exists marathon_teams_touch on public.marathon_teams;
create trigger marathon_teams_touch
  before update on public.marathon_teams
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- marathon_members
--
-- Keyed on email, exactly like purchases: the coach adds «Ваня» from his Telegram group long
-- before Ваня signs in, and the row has to exist for the day plan to mean anything. There is no
-- user_id column — everything that needs "is this me?" compares against current_email(), which is
-- the *verified* address, so an unclaimed row simply has no one matching it yet.
-- -----------------------------------------------------------------------------
create table if not exists public.marathon_members (
  id           uuid primary key default gen_random_uuid(),
  marathon_id  uuid not null references public.marathons (id) on delete cascade,
  email        citext not null check (length(email::text) <= 254),
  team_id      uuid references public.marathon_teams (id) on delete set null,
  -- What the coach calls them. Falls back to the profile's display name, then to a placeholder —
  -- a marathon where half the board reads "Участник" is a marathon nobody can follow.
  display_name text check (display_name is null or length(display_name) <= 60),
  status       text not null default 'active' check (status in ('active', 'removed')),
  note         text check (note is null or length(note) <= 500),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  unique (marathon_id, email)
);

comment on table public.marathon_members is
  'Who plays, by email (like purchases, so they can be added before they sign up). Never read directly by members — see marathon_roster().';

create index if not exists marathon_members_marathon_idx on public.marathon_members (marathon_id, status);
create index if not exists marathon_members_email_idx on public.marathon_members (email);
create index if not exists marathon_members_team_idx on public.marathon_members (team_id);

drop trigger if exists marathon_members_touch on public.marathon_members;
create trigger marathon_members_touch
  before update on public.marathon_members
  for each row execute function public.set_updated_at();

-- Is this a marathon where everyone plays for themselves?
--
-- `team_size = 1` is the whole answer, and it is deliberately the *only* one: a separate mode flag
-- beside a size would let the two disagree. Solo is not "teams that happen to be empty" — every
-- function below reads this and then stops looking at `team_id` at all, so flipping a running
-- marathon to solo really does un-pair everybody rather than leaving stale pairs quietly scoring
-- together.
create or replace function public.marathon_is_solo(p_marathon_id uuid)
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
  select coalesce((select m.team_size from public.marathons m where m.id = p_marathon_id), 2) <= 1;
$$;

-- A team belongs to exactly one marathon, and so does the member pointing at it. Without this a
-- stray update could pair someone with a team from another run and the board would count them twice.
-- A solo marathon has no teams to point at, so a team on a member there is refused outright: the
-- admin screen hides pairing in that mode, and the table should not have to trust the screen.
create or replace function public.marathon_members_check_team()
returns trigger
language plpgsql
set search_path = pg_catalog, public, extensions
as $$
begin
  if new.team_id is not null and not exists (
    select 1 from public.marathon_teams t
    where t.id = new.team_id and t.marathon_id = new.marathon_id
  ) then
    raise exception 'team_from_another_marathon' using errcode = 'P0001';
  end if;
  if new.team_id is not null and public.marathon_is_solo(new.marathon_id) then
    raise exception 'solo_marathon_has_no_teams' using errcode = 'P0001';
  end if;
  return new;
end;
$$;

drop trigger if exists marathon_members_check_team on public.marathon_members;
create trigger marathon_members_check_team
  before insert or update of team_id, marathon_id on public.marathon_members
  for each row execute function public.marathon_members_check_team();

-- -----------------------------------------------------------------------------
-- marathon_tasks — the row the coach writes every morning.
-- -----------------------------------------------------------------------------
create table if not exists public.marathon_tasks (
  id          uuid primary key default gen_random_uuid(),
  marathon_id uuid not null references public.marathons (id) on delete cascade,
  -- 1-based day of the marathon. Day 1 is `starts_on`.
  day_index   int not null check (day_index between 1 and 100),
  sort_order  int not null default 0,

  title       text not null check (length(title) between 1 and 120),
  body        text check (body is null or length(body) <= 4000),
  -- A picture or a clip of him doing it, in the public `images` bucket or any absolute URL.
  media_url   text check (media_url is null or length(media_url) <= 500),

  /*
   * What counts as proof:
   *   done   tap "сделал" — for things he can see in the group anyway
   *   text   a sentence (what you ate, how it went)
   *   number a figure with a unit — the thing the number rules score
   *   media  a photo or a clip, private to the coach (see the `proofs` bucket below)
   */
  proof_kind  text not null default 'done'
              check (proof_kind in ('done', 'text', 'number', 'media')),
  unit        text check (unit is null or length(unit) between 1 and 16),
  -- The figure to beat, when there is one. Purely informational: no rule reads it, because "did
  -- you hit the target" is a judgement the coach makes, not arithmetic.
  target_num  numeric(10, 2) check (target_num is null or target_num >= 0),

  /*
   * How the task scores. Four rules cover every message in his marathon:
   *   all_members  the entry gets `points` only if EVERY active member delivered — his main rule,
   *                the one that makes a pair pull each other through
   *   per_member   every member who delivered earns `points` for the entry
   *   capped       per_member, but the entry's total for this task stops at `cap` ("вдвоём на
   *                второй палубе — не больше N")
   *   none         no points at all: the morning message, a rest day, a tip
   */
  rule        text not null default 'all_members'
              check (rule in ('all_members', 'per_member', 'capped', 'none')),
  points      int not null default 0 check (points between 0 and 1000),
  cap         int check (cap is null or cap between 0 and 10000),

  -- Whether a teammate sees that you delivered (and your text or number). Photos are never shown
  -- to teammates — only to the coach — so this is about the fact and the figure, not the media.
  proof_visibility text not null default 'team' check (proof_visibility in ('team', 'coach')),

  -- Overrides the marathon's `due_time` for this one task ("до обеда").
  due_time    time,
  -- Whether proof after the deadline still scores. Off by default: the deadline is the game.
  late_counts boolean not null default false,

  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

comment on table public.marathon_tasks is
  'One task on one day of a marathon. Who it is for lives in marathon_task_targets; no rows there means everyone.';

-- -----------------------------------------------------------------------------
-- marathon_task_targets — who a task was actually sent to.
--
-- The coach does not think in categories. He opens a day and sends *this* task to *that* pair, or
-- to one person who is behind on something, and someone else that morning gets a different one.
-- An `audience` column with 'all' / 'teams' / 'solo' could not say any of that, so the recipients
-- are rows: a team (the pair does it together) or a single member (it is theirs alone).
--
-- No rows at all means everybody, which is both the common case and the safe default — a task
-- created and never addressed goes to the whole marathon rather than to nobody.
-- -----------------------------------------------------------------------------
create table if not exists public.marathon_task_targets (
  id        uuid primary key default gen_random_uuid(),
  task_id   uuid not null references public.marathon_tasks (id) on delete cascade,
  team_id   uuid references public.marathon_teams (id) on delete cascade,
  member_id uuid references public.marathon_members (id) on delete cascade,
  -- Exactly one of the two: a row is either "this pair" or "this person".
  constraint marathon_task_targets_one check (
    (team_id is not null and member_id is null) or (team_id is null and member_id is not null)
  ),
  unique (task_id, team_id, member_id)
);

comment on table public.marathon_task_targets is
  'Recipients of one task: a team, or one member. No rows for a task means everyone in the marathon.';

create index if not exists marathon_task_targets_task_idx on public.marathon_task_targets (task_id);
create index if not exists marathon_task_targets_team_idx on public.marathon_task_targets (team_id);
create index if not exists marathon_task_targets_member_idx on public.marathon_task_targets (member_id);

-- A number needs a unit to mean anything; a cap only means something for the capped rule.
alter table public.marathon_tasks drop constraint if exists marathon_tasks_unit_required;
alter table public.marathon_tasks add constraint marathon_tasks_unit_required
  check (proof_kind <> 'number' or unit is not null);
alter table public.marathon_tasks drop constraint if exists marathon_tasks_cap_required;
alter table public.marathon_tasks add constraint marathon_tasks_cap_required
  check (case when rule = 'capped' then cap is not null else cap is null end);

create index if not exists marathon_tasks_day_idx
  on public.marathon_tasks (marathon_id, day_index, sort_order);

drop trigger if exists marathon_tasks_touch on public.marathon_tasks;
create trigger marathon_tasks_touch
  before update on public.marathon_tasks
  for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- marathon_submissions — the proof.
-- -----------------------------------------------------------------------------
create table if not exists public.marathon_submissions (
  id          uuid primary key default gen_random_uuid(),
  task_id     uuid not null references public.marathon_tasks (id) on delete cascade,
  member_id   uuid not null references public.marathon_members (id) on delete cascade,
  -- Copied from the task by the guard trigger below, never by the client: every scoring query
  -- filters on these two, and a join per row would turn the board into a nested loop.
  marathon_id uuid not null references public.marathons (id) on delete cascade,
  day_index   int not null,

  value_text  text check (value_text is null or length(value_text) <= 1000),
  value_num   numeric(10, 2) check (value_num is null or value_num >= 0),
  -- Object path inside the private `proofs` bucket, never a URL: the app mints a signed one.
  media_path  text check (media_path is null or length(media_path) <= 300),

  submitted_at timestamptz not null default now(),

  -- Voiding, which is how a wrong or fake proof is undone. The row stays — the coach and the
  -- athlete can both still see what was sent and why it was struck — it simply stops scoring.
  voided_at   timestamptz,
  void_reason text check (void_reason is null or length(void_reason) <= 300),
  voided_by   uuid references auth.users (id) on delete set null,

  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),

  -- One proof per person per task; sending again edits it.
  unique (task_id, member_id)
);

comment on table public.marathon_submissions is
  'One proof per (task, member). Counts from the moment it is written; the coach voids rather than approves.';

create index if not exists marathon_submissions_score_idx
  on public.marathon_submissions (marathon_id, day_index, member_id);
create index if not exists marathon_submissions_task_idx
  on public.marathon_submissions (task_id);
create index if not exists marathon_submissions_feed_idx
  on public.marathon_submissions (marathon_id, submitted_at desc);

drop trigger if exists marathon_submissions_touch on public.marathon_submissions;
create trigger marathon_submissions_touch
  before update on public.marathon_submissions
  for each row execute function public.set_updated_at();

/*
 * The guard: everything a client must not be trusted with.
 *
 * RLS already decides *whether* a row may be written. This decides what it may say — the marathon
 * and the day come from the task, the void fields are the coach's alone, and a submission can
 * never be moved to another task or another person after the fact.
 */
create or replace function public.marathon_submissions_guard()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_task   public.marathon_tasks%rowtype;
  v_member public.marathon_members%rowtype;
  v_admin  boolean := public.is_admin();
begin
  select * into v_task from public.marathon_tasks where id = new.task_id;
  if not found then
    raise exception 'unknown_task' using errcode = 'P0001';
  end if;
  select * into v_member from public.marathon_members where id = new.member_id;
  if not found then
    raise exception 'unknown_member' using errcode = 'P0001';
  end if;
  if v_member.marathon_id <> v_task.marathon_id then
    raise exception 'member_from_another_marathon' using errcode = 'P0001';
  end if;

  new.marathon_id := v_task.marathon_id;
  new.day_index := v_task.day_index;

  if tg_op = 'UPDATE' then
    if new.task_id <> old.task_id or new.member_id <> old.member_id then
      raise exception 'submission_is_fixed_to_its_task_and_member' using errcode = 'P0001';
    end if;
    if not v_admin then
      -- An athlete may correct what they sent. They may not un-void it, and they may not move
      -- when it was sent: editing yesterday's number does not make it yesterday's proof.
      new.voided_at := old.voided_at;
      new.void_reason := old.void_reason;
      new.voided_by := old.voided_by;
      new.submitted_at := old.submitted_at;
    end if;
  elsif not v_admin then
    new.voided_at := null;
    new.void_reason := null;
    new.voided_by := null;
    -- The deadline is the game, so the clock is the server's. The coach keeps the ability to set
    -- it by hand, which is how proof that arrived in Telegram gets entered after the fact.
    new.submitted_at := now();
  end if;

  -- Stamp who struck it, so the feed can say so without a second write.
  if new.voided_at is not null and new.voided_by is null then
    new.voided_by := auth.uid();
  end if;

  return new;
end;
$$;

drop trigger if exists marathon_submissions_guard on public.marathon_submissions;
create trigger marathon_submissions_guard
  before insert or update on public.marathon_submissions
  for each row execute function public.marathon_submissions_guard();

-- -----------------------------------------------------------------------------
-- marathon_adjustments — the coach's ±points, with a reason.
--
-- «Плюс пять за то, что вытащил напарника» is not expressible as a task, and pretending otherwise
-- would mean inventing a fake task every time. It is a separate, always-visible line instead.
-- -----------------------------------------------------------------------------
create table if not exists public.marathon_adjustments (
  id          uuid primary key default gen_random_uuid(),
  marathon_id uuid not null references public.marathons (id) on delete cascade,
  member_id   uuid not null references public.marathon_members (id) on delete cascade,
  day_index   int not null check (day_index between 1 and 100),
  points      int not null check (points between -1000 and 1000),
  reason      text not null check (length(reason) between 1 and 300),
  created_by  uuid references auth.users (id) on delete set null,
  created_at  timestamptz not null default now()
);

comment on table public.marathon_adjustments is 'Manual ±points from the coach, always with a reason. Counted by marathon_scores() like any task.';

create index if not exists marathon_adjustments_score_idx
  on public.marathon_adjustments (marathon_id, day_index, member_id);

-- =============================================================================
-- Helpers. All security definer: they are the only way a member learns anything about a
-- marathon's people, and they must read tables the caller has no policy on.
-- =============================================================================

-- The caller's member row in this marathon, or null. The single question every policy below asks.
create or replace function public.marathon_member_id(p_marathon_id uuid)
returns uuid
language sql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
  select m.id
  from public.marathon_members m
  where m.marathon_id = p_marathon_id
    and m.status = 'active'
    and m.email = public.current_email()
  limit 1;
$$;

create or replace function public.is_marathon_member(p_marathon_id uuid)
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
  select public.marathon_member_id(p_marathon_id) is not null;
$$;

/*
 * Which day of the marathon it is, in the marathon's own timezone.
 *   0          it has not started yet
 *   1..days    today
 *   days + 1…  it is over (the caller clamps for display; scoring ignores days past the end)
 */
create or replace function public.marathon_day_index(p_marathon_id uuid)
returns int
language sql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
  select greatest(0, ((now() at time zone m.timezone)::date - m.starts_on) + 1)
  from public.marathons m
  where m.id = p_marathon_id;
$$;

/*
 * The two predicates the submission policies ask, as security-definer functions rather than as
 * sub-selects inside the policy.
 *
 * A policy body is evaluated as the *caller*, so row-level security applies to everything it reads
 * too: a sub-select over marathon_members inside a policy sees nothing, because members have no
 * select on that table. Asking the question in a definer function is the only way to answer it at
 * all, and it keeps the rule in one readable place instead of spread across three policies.
 */

-- Was this task sent to me? No recipients at all means it went to everyone; otherwise I am named,
-- or my team is. Row-level security asks this, so a task the coach aimed at one pair is not merely
-- unscored for everybody else — it is not on their screen at all.
create or replace function public.marathon_task_is_for_me(p_task_id uuid)
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
  select exists (
    select 1
    from public.marathon_tasks t
    join public.marathon_members mem
      on mem.marathon_id = t.marathon_id
     and mem.status = 'active'
     and mem.email = public.current_email()
    where t.id = p_task_id
      and (
        not exists (select 1 from public.marathon_task_targets g where g.task_id = t.id)
        or exists (
          select 1 from public.marathon_task_targets g
          where g.task_id = t.id
            and (
              g.member_id = mem.id
              -- A target left over from before the marathon was switched to solo names a team
              -- nobody is in any more; it must not keep delivering tasks.
              or (g.team_id is not null and g.team_id = mem.team_id
                  and not public.marathon_is_solo(t.marathon_id))
            )
        )
      )
  );
$$;

-- May this task be written to right now? The marathon is running and the day has arrived. Whether
-- proof this late still *scores* is the task's own business (late_counts) — it is recorded either way.
create or replace function public.marathon_task_is_open(p_task_id uuid)
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
  select exists (
    select 1
    from public.marathon_tasks t
    join public.marathons m on m.id = t.marathon_id
    where t.id = p_task_id
      and m.status = 'active'
      and t.day_index <= public.marathon_day_index(m.id)
  );
$$;

-- Is this someone else's proof that I am entitled to see? Only a teammate's, and only when the
-- task shares it with the team. Media never travels this way — the object in the bucket has its
-- own, stricter rule.
create or replace function public.can_read_teammate_proof(p_marathon_id uuid, p_member_id uuid, p_task_id uuid)
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
  select exists (
    select 1
    from public.marathon_members mine
    join public.marathon_members theirs
      on theirs.marathon_id = mine.marathon_id
     and theirs.team_id = mine.team_id
    join public.marathon_tasks t on t.id = p_task_id
    where mine.id = public.marathon_member_id(p_marathon_id)
      and mine.team_id is not null
      -- In a solo marathon there are no teammates, so `proof_visibility = 'team'` means the author
      -- and the coach. Guarded here as well as by the empty teams, so that flipping a running
      -- marathon to solo closes the sharing immediately rather than when the pairs are deleted.
      and not public.marathon_is_solo(p_marathon_id)
      and theirs.id = p_member_id
      and theirs.status = 'active'
      and t.proof_visibility = 'team'
  );
$$;

-- Week 1 is days 1..7, counted from the marathon's own start rather than from Monday.
create or replace function public.marathon_week_of(p_day_index int)
returns int
language sql
immutable
as $$
  select case when p_day_index is null or p_day_index < 1 then null
              else ((p_day_index - 1) / 7) + 1 end;
$$;

revoke execute on function public.marathon_member_id(uuid) from public, anon;
revoke execute on function public.is_marathon_member(uuid) from public, anon;
revoke execute on function public.marathon_day_index(uuid) from public, anon;
revoke execute on function public.marathon_task_is_open(uuid) from public, anon;
revoke execute on function public.marathon_task_is_for_me(uuid) from public, anon;
revoke execute on function public.can_read_teammate_proof(uuid, uuid, uuid) from public, anon;
grant execute on function public.marathon_member_id(uuid) to authenticated;
grant execute on function public.is_marathon_member(uuid) to authenticated;
grant execute on function public.marathon_day_index(uuid) to authenticated;
grant execute on function public.marathon_task_is_open(uuid) to authenticated;
grant execute on function public.marathon_task_is_for_me(uuid) to authenticated;
grant execute on function public.can_read_teammate_proof(uuid, uuid, uuid) to authenticated;
grant execute on function public.marathon_week_of(int) to authenticated;

-- =============================================================================
-- Row-level security
-- =============================================================================

alter table public.marathons enable row level security;
alter table public.marathon_teams enable row level security;
alter table public.marathon_members enable row level security;
alter table public.marathon_tasks enable row level security;
alter table public.marathon_task_targets enable row level security;
alter table public.marathon_submissions enable row level security;
alter table public.marathon_adjustments enable row level security;

-- marathons ------------------------------------------------------------------
drop policy if exists "marathons: admins all" on public.marathons;
create policy "marathons: admins all"
  on public.marathons for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- A member sees their own marathon, and only once it has started running: a draft is the coach
-- still writing it.
drop policy if exists "marathons: members read" on public.marathons;
create policy "marathons: members read"
  on public.marathons for select
  to authenticated
  using (status in ('active', 'finished') and public.is_marathon_member(id));

-- marathon_teams ---------------------------------------------------------------
drop policy if exists "marathon_teams: admins all" on public.marathon_teams;
create policy "marathon_teams: admins all"
  on public.marathon_teams for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

drop policy if exists "marathon_teams: members read" on public.marathon_teams;
create policy "marathon_teams: members read"
  on public.marathon_teams for select
  to authenticated
  using (public.is_marathon_member(marathon_id));

-- marathon_members -------------------------------------------------------------
-- Admins only. The row carries an email and the coach's private note; members learn who is playing
-- through marathon_roster(), which returns names and nothing else.
drop policy if exists "marathon_members: admins all" on public.marathon_members;
create policy "marathon_members: admins all"
  on public.marathon_members for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- marathon_tasks ---------------------------------------------------------------
drop policy if exists "marathon_tasks: admins all" on public.marathon_tasks;
create policy "marathon_tasks: admins all"
  on public.marathon_tasks for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

/*
 * Members read today's tasks and every day before it — never tomorrow's. Reading ahead would spoil
 * the format (the task arrives in the morning and that is the event), and it is the client's only
 * source for the day plan, so the rule belongs here rather than in a query the app could forget.
 */
drop policy if exists "marathon_tasks: members read up to today" on public.marathon_tasks;
create policy "marathon_tasks: members read up to today"
  on public.marathon_tasks for select
  to authenticated
  using (
    public.is_marathon_member(marathon_id)
    and day_index <= public.marathon_day_index(marathon_id)
    and public.marathon_task_is_for_me(id)
  );

-- marathon_task_targets ---------------------------------------------------------
-- Admins only. A member never needs to read it: the task list they can see is already filtered by
-- `marathon_task_is_for_me`, and who *else* a task went to is not theirs to know.
drop policy if exists "marathon_task_targets: admins all" on public.marathon_task_targets;
create policy "marathon_task_targets: admins all"
  on public.marathon_task_targets for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- marathon_submissions ---------------------------------------------------------
drop policy if exists "marathon_submissions: admins all" on public.marathon_submissions;
create policy "marathon_submissions: admins all"
  on public.marathon_submissions for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

drop policy if exists "marathon_submissions: own read" on public.marathon_submissions;
create policy "marathon_submissions: own read"
  on public.marathon_submissions for select
  to authenticated
  using (member_id = public.marathon_member_id(marathon_id));

/*
 * A teammate's proof, when the task says 'team'. This is what makes «Ваня сделал, ждём Витю» show
 * up on your own screen — the state of the person you are scored with. Media stays out of it: the
 * row is visible, the object in the `proofs` bucket is not.
 */
drop policy if exists "marathon_submissions: teammate read" on public.marathon_submissions;
create policy "marathon_submissions: teammate read"
  on public.marathon_submissions for select
  to authenticated
  using (public.can_read_teammate_proof(marathon_id, member_id, task_id));

/*
 * Writing proof. Only for yourself, only on a running marathon, and only for a day that has
 * actually arrived. Whether a late proof *scores* is the task's business (`late_counts`) — it is
 * still recorded either way, because the coach wants to see that it was done at all.
 */
drop policy if exists "marathon_submissions: own write" on public.marathon_submissions;
create policy "marathon_submissions: own write"
  on public.marathon_submissions for insert
  to authenticated
  with check (
    member_id = public.marathon_member_id(marathon_id)
    and public.marathon_task_is_open(task_id)
    and public.marathon_task_is_for_me(task_id)
  );

drop policy if exists "marathon_submissions: own update" on public.marathon_submissions;
create policy "marathon_submissions: own update"
  on public.marathon_submissions for update
  to authenticated
  using (
    member_id = public.marathon_member_id(marathon_id)
    and voided_at is null
    and public.marathon_task_is_open(task_id)
  )
  with check (member_id = public.marathon_member_id(marathon_id));

-- No delete policy for members on purpose: a proof that was sent is part of the record. Correcting
-- it is an update; removing it is the coach's call.

-- marathon_adjustments ---------------------------------------------------------
drop policy if exists "marathon_adjustments: admins all" on public.marathon_adjustments;
create policy "marathon_adjustments: admins all"
  on public.marathon_adjustments for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

-- You can always see why your own total moved.
drop policy if exists "marathon_adjustments: own read" on public.marathon_adjustments;
create policy "marathon_adjustments: own read"
  on public.marathon_adjustments for select
  to authenticated
  using (member_id = public.marathon_member_id(marathon_id));

revoke all on public.marathons from anon, authenticated;
revoke all on public.marathon_teams from anon, authenticated;
revoke all on public.marathon_members from anon, authenticated;
revoke all on public.marathon_tasks from anon, authenticated;
revoke all on public.marathon_task_targets from anon, authenticated;
revoke all on public.marathon_submissions from anon, authenticated;
revoke all on public.marathon_adjustments from anon, authenticated;

grant select, insert, update, delete on public.marathons to authenticated;
grant select, insert, update, delete on public.marathon_teams to authenticated;
grant select, insert, update, delete on public.marathon_members to authenticated;
grant select, insert, update, delete on public.marathon_tasks to authenticated;
grant select, insert, update, delete on public.marathon_task_targets to authenticated;
grant select, insert, update, delete on public.marathon_submissions to authenticated;
grant select, insert, update, delete on public.marathon_adjustments to authenticated;

-- =============================================================================
-- proofs — a private bucket for photo and video proof.
--
-- Private, unlike `images`: this is someone's kitchen, their scales, their living-room floor. Only
-- the athlete who sent it and the coach can read it, and a teammate cannot — a pair shares a score,
-- not a camera roll.
--
-- Object naming: proofs/<marathon_id>/<member_id>/<task_id>.<ext>
-- =============================================================================
insert into storage.buckets (id, name, public)
values ('proofs', 'proofs', false)
on conflict (id) do nothing;

-- Does this object path belong to the caller? Both segments have to match: the marathon they are
-- in, and their own member id inside it.
create or replace function public.owns_proof_path(p_name text)
returns boolean
language plpgsql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_parts text[] := storage.foldername(p_name);
  v_marathon uuid;
  v_member uuid;
begin
  if array_length(v_parts, 1) is null or array_length(v_parts, 1) < 2 then
    return false;
  end if;
  begin
    v_marathon := v_parts[1]::uuid;
    v_member := v_parts[2]::uuid;
  exception when others then
    return false;
  end;
  return v_member = public.marathon_member_id(v_marathon);
end;
$$;

revoke execute on function public.owns_proof_path(text) from public, anon;
grant execute on function public.owns_proof_path(text) to authenticated;

drop policy if exists "proofs: admin all" on storage.objects;
create policy "proofs: admin all"
  on storage.objects for all
  to authenticated
  using (bucket_id = 'proofs' and public.is_admin())
  with check (bucket_id = 'proofs' and public.is_admin());

drop policy if exists "proofs: own read" on storage.objects;
create policy "proofs: own read"
  on storage.objects for select
  to authenticated
  using (bucket_id = 'proofs' and public.owns_proof_path(name));

drop policy if exists "proofs: own insert" on storage.objects;
create policy "proofs: own insert"
  on storage.objects for insert
  to authenticated
  with check (bucket_id = 'proofs' and public.owns_proof_path(name));

-- Re-sending proof replaces the object; the path is derived from the task, so it is the same key.
drop policy if exists "proofs: own update" on storage.objects;
create policy "proofs: own update"
  on storage.objects for update
  to authenticated
  using (bucket_id = 'proofs' and public.owns_proof_path(name))
  with check (bucket_id = 'proofs' and public.owns_proof_path(name));

-- =============================================================================
-- The read API.
--
-- Four functions, all security definer, all checking membership themselves. They exist because
-- every one of them has to read rows the caller has no policy on (other people's member rows) or
-- do arithmetic that must be identical for everybody (the board).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- my_marathons — everything the app needs to open the format at all.
-- -----------------------------------------------------------------------------
create or replace function public.my_marathons()
returns table (
  id          uuid,
  slug        text,
  title       text,
  description text,
  status      text,
  starts_on   date,
  days        int,
  team_size   int,
  prize       text,
  day_index   int,
  week        int,
  total_weeks int,
  member_id   uuid,
  team_id     uuid,
  team_name   text
)
language sql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
  select
    m.id, m.slug, m.title, m.description, m.status, m.starts_on, m.days, m.team_size, m.prize,
    least(public.marathon_day_index(m.id), m.days) as day_index,
    public.marathon_week_of(least(public.marathon_day_index(m.id), m.days)) as week,
    public.marathon_week_of(m.days) as total_weeks,
    mem.id, mem.team_id, t.name
  from public.marathons m
  join public.marathon_members mem
    on mem.marathon_id = m.id
   and mem.status = 'active'
   and mem.email = public.current_email()
  left join public.marathon_teams t on t.id = mem.team_id
  where m.status in ('active', 'finished')
  order by m.starts_on desc;
$$;

revoke execute on function public.my_marathons() from public, anon;
grant execute on function public.my_marathons() to authenticated;

-- -----------------------------------------------------------------------------
-- marathon_roster — who is playing, by name. No emails, ever.
-- -----------------------------------------------------------------------------
create or replace function public.marathon_roster(p_marathon_id uuid)
returns table (
  member_id    uuid,
  display_name text,
  team_id      uuid,
  team_name    text,
  is_me        boolean
)
language plpgsql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_me uuid := public.marathon_member_id(p_marathon_id);
begin
  if v_me is null and not public.is_admin() then
    raise exception 'not_a_member' using errcode = '42501';
  end if;

  return query
  select
    mem.id,
    left(coalesce(
      nullif(trim(mem.display_name), ''),
      nullif(trim(p.display_name), ''),
      'Участник'
    ), 60),
    mem.team_id,
    t.name,
    mem.id = v_me
  from public.marathon_members mem
  left join public.marathon_teams t on t.id = mem.team_id
  left join public.profiles p on p.email = mem.email
  where mem.marathon_id = p_marathon_id
    and mem.status = 'active'
  order by t.sort_order nulls last, t.name nulls last, mem.created_at;
end;
$$;

revoke execute on function public.marathon_roster(uuid) from public, anon;
grant execute on function public.marathon_roster(uuid) to authenticated;

-- -----------------------------------------------------------------------------
-- marathon_scores — the board.
--
-- An *entry* is what races: a team, or a member with no team (their own entry of one). That single
-- idea is what lets one function serve a paired marathon, a solo one, and a mixed one, and it is
-- why `all_members` needs no special case for someone playing alone — a team of one is satisfied
-- by one person.
--
-- p_week null means the current week. Week 0 does not exist; before a marathon starts every entry
-- is simply on zero.
-- -----------------------------------------------------------------------------
create or replace function public.marathon_scores(p_marathon_id uuid, p_week int default null)
returns table (
  entry_kind  text,
  entry_id    uuid,
  title       text,
  members     text[],
  points      bigint,
  rank        bigint,
  is_mine     boolean
)
language plpgsql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_me   uuid := public.marathon_member_id(p_marathon_id);
  v_m    public.marathons%rowtype;
  v_week int;
  -- Solo: every member is their own entry and no team is consulted, whatever the teams table says.
  v_solo boolean;
begin
  if v_me is null and not public.is_admin() then
    raise exception 'not_a_member' using errcode = '42501';
  end if;

  select * into v_m from public.marathons where id = p_marathon_id;
  if not found then
    raise exception 'unknown_marathon' using errcode = 'P0001';
  end if;
  v_solo := coalesce(v_m.team_size, 2) <= 1;

  v_week := coalesce(
    p_week,
    public.marathon_week_of(least(greatest(public.marathon_day_index(p_marathon_id), 1), v_m.days)),
    1
  );
  if v_week < 1 then
    raise exception 'invalid_week' using errcode = 'P0001';
  end if;

  return query
  with
  -- Every active member, with the entry they race in and the name to show.
  people as (
    select
      mem.id as member_id,
      case when v_solo then mem.id else coalesce(mem.team_id, mem.id) end as entry_id,
      case when not v_solo and mem.team_id is not null then 'team' else 'solo' end as entry_kind,
      coalesce(
        case when v_solo then null else t.name end,
        nullif(trim(mem.display_name), ''),
        nullif(trim(p.display_name), ''),
        'Участник'
      ) as entry_title,
      left(coalesce(
        nullif(trim(mem.display_name), ''),
        nullif(trim(p.display_name), ''),
        'Участник'
      ), 60) as member_name,
      case when v_solo then 0 else coalesce(t.sort_order, 0) end as sort_order,
      case when v_solo then null else mem.team_id end as team_id,
      mem.created_at
    from public.marathon_members mem
    left join public.marathon_teams t on t.id = mem.team_id
    left join public.profiles p on p.email = mem.email
    where mem.marathon_id = p_marathon_id
      and mem.status = 'active'
  ),
  entries as (
    select
      pe.entry_id,
      min(pe.entry_kind) as entry_kind,
      min(pe.entry_title) as title,
      array_agg(pe.member_name order by pe.created_at) as members,
      count(*)::int as member_count,
      min(pe.sort_order) as sort_order,
      bool_or(pe.member_id = v_me) as is_mine
    from people pe
    group by pe.entry_id
  ),
  -- The tasks of this week that actually happened: a day past the end of the marathon is not a day.
  week_tasks as (
    select t.*
    from public.marathon_tasks t
    where t.marathon_id = p_marathon_id
      and t.day_index <= v_m.days
      and public.marathon_week_of(t.day_index) = v_week
      and t.rule <> 'none'
  ),
  -- Proof that counts: not voided, and in time unless the task forgives lateness.
  counted as (
    select s.task_id, s.member_id
    from public.marathon_submissions s
    join week_tasks t on t.id = s.task_id
    where s.marathon_id = p_marathon_id
      and s.voided_at is null
      and (
        t.late_counts
        or s.submitted_at <= (
          ((v_m.starts_on + (t.day_index - 1))::timestamp + coalesce(t.due_time, v_m.due_time))
          at time zone v_m.timezone
        )
      )
  ),
  /*
   * Who each task was actually sent to.
   *
   * A task with no target rows went to everyone; otherwise a person is a recipient when they are
   * named, or when their team is. This is the join that replaced an `audience` column, and it is
   * also what makes the rules below read the same for a task sent to the whole marathon and one
   * sent to a single person: the rule always applies over *the recipients inside this entry*.
   */
  recipients as (
    select t.id as task_id, t.rule, t.points, t.cap, pe.entry_id, pe.member_id
    from week_tasks t
    join people pe
      on not exists (select 1 from public.marathon_task_targets g where g.task_id = t.id)
      or exists (
        select 1
        from public.marathon_task_targets g
        where g.task_id = t.id
          and (g.member_id = pe.member_id
               or (not v_solo and g.team_id is not null and g.team_id = pe.team_id))
      )
  ),
  -- How many of an entry's recipients delivered each task, and how many were asked.
  per_task as (
    select
      r.entry_id,
      r.task_id,
      min(r.rule) as rule,
      min(r.points) as points,
      min(r.cap) as cap,
      count(*)::int as asked,
      count(c.member_id)::int as done
    from recipients r
    left join counted c on c.task_id = r.task_id and c.member_id = r.member_id
    group by r.entry_id, r.task_id
  ),
  task_points as (
    select
      pt.entry_id,
      sum(
        case pt.rule
          -- "Everyone" means everyone it was sent to, which for a task aimed at one member of a
          -- pair is that one member.
          when 'all_members' then case when pt.done >= pt.asked then pt.points else 0 end
          when 'per_member'  then pt.done * pt.points
          when 'capped'      then least(pt.done * pt.points, pt.cap)
          else 0
        end
      )::bigint as pts
    from per_task pt
    group by pt.entry_id
  ),
  -- The coach's ±points, for the same week, credited to the member's entry.
  adjust as (
    select pe.entry_id, sum(a.points)::bigint as pts
    from public.marathon_adjustments a
    join people pe on pe.member_id = a.member_id
    where a.marathon_id = p_marathon_id
      and public.marathon_week_of(a.day_index) = v_week
    group by pe.entry_id
  ),
  totals as (
    select
      e.entry_id,
      e.entry_kind,
      e.title,
      e.members,
      e.sort_order,
      e.is_mine,
      greatest(coalesce(tp.pts, 0) + coalesce(ad.pts, 0), 0) as pts
    from entries e
    left join task_points tp on tp.entry_id = e.entry_id
    left join adjust ad on ad.entry_id = e.entry_id
  )
  select
    tt.entry_kind,
    tt.entry_id,
    left(tt.title, 60),
    tt.members,
    tt.pts,
    rank() over (order by tt.pts desc, tt.sort_order, tt.title)::bigint,
    tt.is_mine
  from totals tt
  order by 6, tt.sort_order, tt.title;
end;
$$;

revoke execute on function public.marathon_scores(uuid, int) from public, anon;
grant execute on function public.marathon_scores(uuid, int) to authenticated;

-- -----------------------------------------------------------------------------
-- marathon_my_points — the caller's marathon, day by day.
--
-- Two different numbers, deliberately side by side: how many of the day's tasks *you* delivered,
-- and how many points your *entry* took. In a paired marathon those come apart — that is the whole
-- tension of the format, and the screen should show it rather than hide it behind one total.
-- -----------------------------------------------------------------------------
create or replace function public.marathon_my_points(p_marathon_id uuid)
returns table (
  day_index   int,
  week        int,
  tasks_total int,
  tasks_done  int,
  points      bigint
)
language plpgsql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_me   uuid := public.marathon_member_id(p_marathon_id);
  v_m    public.marathons%rowtype;
  v_today int;
  v_solo boolean;
begin
  if v_me is null then
    raise exception 'not_a_member' using errcode = '42501';
  end if;

  select * into v_m from public.marathons where id = p_marathon_id;
  v_solo := coalesce(v_m.team_size, 2) <= 1;
  v_today := least(public.marathon_day_index(p_marathon_id), v_m.days);
  if v_today < 1 then
    return;
  end if;

  return query
  with days as (
    select generate_series(1, v_today) as d
  ),
  mine as (
    select
      mem.id as member_id,
      case when v_solo then null else mem.team_id end as team_id,
      case when v_solo then mem.id else coalesce(mem.team_id, mem.id) end as entry_id
    from public.marathon_members mem where mem.id = v_me
  ),
  /*
   * The tasks I was actually sent, per day.
   *
   * Only the ones that score: the morning message goes to everyone and is worth nothing, and
   * counting it would tell someone they had missed 1 of 3 for not ticking «Доброе утро».
   */
  my_tasks as (
    select t.*
    from public.marathon_tasks t, mine
    where t.marathon_id = p_marathon_id
      and t.day_index <= v_today
      and t.rule <> 'none'
      and (
        not exists (select 1 from public.marathon_task_targets g where g.task_id = t.id)
        or exists (
          select 1 from public.marathon_task_targets g
          where g.task_id = t.id
            and (g.member_id = mine.member_id
                 or (not v_solo and g.team_id is not null and g.team_id = mine.team_id))
        )
      )
  ),
  done as (
    select s.day_index, count(*)::int as n
    from public.marathon_submissions s
    join my_tasks t on t.id = s.task_id
    where s.member_id = v_me and s.voided_at is null
    group by s.day_index
  ),
  totals as (
    select t.day_index, count(*)::int as n from my_tasks t group by t.day_index
  ),
  -- The same "proof that counts" rule as the board, narrowed to my entry: not voided, and in time
  -- unless the task forgives lateness. Scored per day here rather than per week, so the screen can
  -- show which day the points came from; summing these days over a week gives the board's figure.
  counted as (
    select s.task_id, s.member_id, t.day_index
    from public.marathon_submissions s
    join my_tasks t on t.id = s.task_id
    join public.marathon_members mem on mem.id = s.member_id
    where s.voided_at is null
      and mem.marathon_id = p_marathon_id
      and mem.status = 'active'
      and (case when v_solo then mem.id else coalesce(mem.team_id, mem.id) end)
            = (select entry_id from mine)
      and (
        t.late_counts
        or s.submitted_at <= (
          ((v_m.starts_on + (t.day_index - 1))::timestamp + coalesce(t.due_time, v_m.due_time))
          at time zone v_m.timezone
        )
      )
  ),
  -- Everyone in my entry the task was sent to — the same question the board asks, narrowed to me.
  asked as (
    select t.id as task_id, count(*)::int as n
    from my_tasks t
    join public.marathon_members mem
      on mem.marathon_id = p_marathon_id
     and mem.status = 'active'
     and (case when v_solo then mem.id else coalesce(mem.team_id, mem.id) end)
           = (select entry_id from mine)
     and (
       not exists (select 1 from public.marathon_task_targets g where g.task_id = t.id)
       or exists (
         select 1 from public.marathon_task_targets g
         where g.task_id = t.id
           and (g.member_id = mem.id or (g.team_id is not null and g.team_id = mem.team_id))
       )
     )
    group by t.id
  ),
  per_task as (
    select t.day_index, t.rule, t.points, t.cap,
           coalesce((select n from asked a where a.task_id = t.id), 0) as asked_n,
           (select count(*) from counted c where c.task_id = t.id)::int as done_n
    from my_tasks t
  ),
  day_points as (
    select pt.day_index,
           sum(
             case pt.rule
               when 'all_members' then case when pt.asked_n > 0 and pt.done_n >= pt.asked_n then pt.points else 0 end
               when 'per_member'  then pt.done_n * pt.points
               when 'capped'      then least(pt.done_n * pt.points, pt.cap)
               else 0
             end
           )::bigint as pts
    from per_task pt
    group by pt.day_index
  ),
  day_adjust as (
    select a.day_index, sum(a.points)::bigint as pts
    from public.marathon_adjustments a
    join public.marathon_members mem on mem.id = a.member_id
    where a.marathon_id = p_marathon_id
      and (case when v_solo then mem.id else coalesce(mem.team_id, mem.id) end)
            = (select entry_id from mine)
    group by a.day_index
  )
  select
    days.d,
    public.marathon_week_of(days.d),
    coalesce(tot.n, 0),
    coalesce(dn.n, 0),
    coalesce(dp.pts, 0) + coalesce(da.pts, 0)
  from days
  left join totals tot on tot.day_index = days.d
  left join done dn on dn.day_index = days.d
  left join day_points dp on dp.day_index = days.d
  left join day_adjust da on da.day_index = days.d
  order by days.d desc;
end;
$$;

revoke execute on function public.marathon_my_points(uuid) from public, anon;
grant execute on function public.marathon_my_points(uuid) to authenticated;

-- =============================================================================
-- 0012_step_proofs.sql — a screenshot attached to a day's steps.
-- =============================================================================

-- =============================================================================
-- 0012 — a screenshot attached to a day's steps.
--
-- Steps are typed in by hand (docs/SPEC.md §7), which is the honest arrangement — no phone health
-- API is reachable from a Mini App — and it is also the one place in the product where the number
-- that earns points is the athlete's own word. A screenshot of the phone's own step counter is
-- what turns that word into something the coach can look at, and for the athlete it is faster than
-- typing: open Здоровье, screenshot, attach.
--
-- Nothing here scores it and nothing verifies it. The points still come from `steps` through the
-- same trigger; the image is evidence a person can read, filed next to the number.
--
-- Safe to re-run: every policy is dropped first and every function is `create or replace`.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- daily_logs.proof_path — an object in the private `proofs` bucket, never a URL.
-- -----------------------------------------------------------------------------
alter table public.daily_logs add column if not exists proof_path text;

alter table public.daily_logs drop constraint if exists daily_logs_proof_path_len;
alter table public.daily_logs add constraint daily_logs_proof_path_len
  check (proof_path is null or length(proof_path) between 1 and 400)
  not valid;

comment on column public.daily_logs.proof_path is
  'storage:proofs/steps/<user_id>/<local_date>.<ext> — the athlete''s own screenshot of their step counter. Never a URL: the app mints a signed one.';

-- -----------------------------------------------------------------------------
-- The bucket. Declared here as well as in 0011 so step proofs do not depend on the marathon
-- migration having been run; `on conflict do nothing` makes the second declaration a no-op.
-- -----------------------------------------------------------------------------
insert into storage.buckets (id, name, public)
values ('proofs', 'proofs', false)
on conflict (id) do nothing;

/*
 * Is this object inside the caller's own steps folder?
 *
 * The path is `steps/<user_id>/<anything>`, so the check is the second folder against the caller.
 * Security definer only to keep it callable without a grant on anything it reads; it reads nothing
 * but the JWT.
 */
create or replace function public.owns_step_proof_path(p_name text)
returns boolean
language plpgsql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_parts text[] := storage.foldername(p_name);
  v_owner uuid;
begin
  if array_length(v_parts, 1) is null or array_length(v_parts, 1) < 2 then
    return false;
  end if;
  if v_parts[1] <> 'steps' then
    return false;
  end if;
  begin
    v_owner := v_parts[2]::uuid;
  exception when others then
    return false;
  end;
  return v_owner = auth.uid();
end;
$$;

revoke execute on function public.owns_step_proof_path(text) from public, anon;
grant execute on function public.owns_step_proof_path(text) to authenticated;

/*
 * The athlete owns their screenshots outright: upload, replace, look at, delete. The coach reads
 * everything in this bucket already (the "proofs: admin all" policy from 0011, restated here so
 * the two migrations are independent) — that is the point of a proof.
 */
drop policy if exists "proofs: admin all" on storage.objects;
create policy "proofs: admin all"
  on storage.objects for all
  to authenticated
  using (bucket_id = 'proofs' and public.is_admin())
  with check (bucket_id = 'proofs' and public.is_admin());

drop policy if exists "proofs: steps own read" on storage.objects;
create policy "proofs: steps own read"
  on storage.objects for select
  to authenticated
  using (bucket_id = 'proofs' and public.owns_step_proof_path(name));

drop policy if exists "proofs: steps own insert" on storage.objects;
create policy "proofs: steps own insert"
  on storage.objects for insert
  to authenticated
  with check (bucket_id = 'proofs' and public.owns_step_proof_path(name));

drop policy if exists "proofs: steps own update" on storage.objects;
create policy "proofs: steps own update"
  on storage.objects for update
  to authenticated
  using (bucket_id = 'proofs' and public.owns_step_proof_path(name))
  with check (bucket_id = 'proofs' and public.owns_step_proof_path(name));

drop policy if exists "proofs: steps own delete" on storage.objects;
create policy "proofs: steps own delete"
  on storage.objects for delete
  to authenticated
  using (bucket_id = 'proofs' and public.owns_step_proof_path(name));

-- =============================================================================
-- 0013_admin_people.sql — admin_people — everybody who has signed in, for the admin to pick from.
-- =============================================================================

-- =============================================================================
-- admin_people — everybody who has signed in, for the admin to pick from.
--
-- «В админку показывай всех пользователей которые прошли активацию чтобы я могла
-- не писать а пролистать все почты и выбрать кому накинуть курс или подписку.»
--
-- Granting a course or a subscription meant typing an address from memory into a
-- field that only tells you it was wrong after you submit it. One letter out and
-- the grant lands on an account that does not exist, silently: `admin_add_purchase`
-- takes any well-formed address, because a pre-sale grant to somebody who has not
-- signed up yet is a real thing the coach does. So the check cannot live there —
-- it has to be a list you choose from instead of a box you type into.
--
-- "Прошла активацию" means: there is a row in `public.profiles`. A profile is
-- created by the trigger on `auth.users` once the one-time code has been confirmed,
-- so a profile is exactly the set of people who got in. It is read here rather than
-- `auth.users` because the app's own table is the one that carries the display name
-- and the onboarding state, and because reaching into `auth` from a function the
-- client can call is a habit worth not having.
--
-- What it returns, per person: the address, what they call themselves, when they
-- first signed in, whether they finished onboarding, how many courses they already
-- hold, and whether a subscription is live. Those last two are what make the list
-- usable — the point is to pick somebody who does *not* already have the thing you
-- were about to give them.
-- =============================================================================

create or replace function public.admin_people(
  p_search text default null,
  p_limit  int  default 500
)
returns table (
  email        citext,
  display_name text,
  created_at   timestamptz,
  onboarded_at timestamptz,
  courses      int,
  subscribed   boolean
)
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_term text;
begin
  if not public.is_admin() then
    raise exception 'not_admin' using errcode = '42501';
  end if;

  -- A substring match on the address or the name, or everybody when it is empty.
  -- `%` and `_` are escaped so a pasted address cannot turn into a wildcard scan.
  v_term := nullif(trim(coalesce(p_search, '')), '');
  if v_term is not null then
    v_term := '%' || replace(replace(v_term, '\', '\\'), '%', '\%') || '%';
    v_term := replace(v_term, '_', '\_');
  end if;

  return query
  select
    p.email,
    p.display_name,
    p.created_at,
    p.onboarded_at,
    /*
     * Active grants only. A refunded purchase is history and a person holding one is
     * a person with nothing — showing it as a course they have would be the list
     * telling the coach not to give them the thing they are owed.
     */
    (
      select count(*)::int
      from public.purchases pu
      where pu.email = p.email and pu.status = 'active'
    ) as courses,
    /*
     * `subscription_live()` rather than a status check written again here. A cancelled
     * subscription still has access until it expires (0005_subscriptions.sql), and a
     * second copy of that rule is a second place for it to drift.
     */
    exists (
      select 1
      from public.subscriptions s
      where s.email = p.email
        and public.subscription_live(s.status, s.expires_at)
    ) as subscribed
  from public.profiles p
  where v_term is null
     or p.email::text ilike v_term escape '\'
     or coalesce(p.display_name, '') ilike v_term escape '\'
  order by p.created_at desc
  limit greatest(1, least(coalesce(p_limit, 500), 1000));
end;
$$;

comment on function public.admin_people(text, int) is
  'Admin-only: everybody with a profile (i.e. who confirmed a sign-in code), with what they already hold.';

revoke execute on function public.admin_people(text, int) from public, anon;
grant execute on function public.admin_people(text, int) to authenticated;

-- =============================================================================
-- 0014_coach_bookings.sql — Coach bookings: the one-to-one session a person booked with the coach.
-- =============================================================================

-- =============================================================================
-- 0014 — Coach bookings: the one-to-one session a person booked with the coach.
--
-- «Будет здорово если мы будем подгружать в приложение информацию о встрече которую сделал
--  пользователь. Типо вот ссылка на вход, через столько то начнется, дата, время»
--
-- The Тренер tab used to end at "pay and write to the coach". Bookings now happen in a scheduling
-- tool, and this table is the app's copy of them: one row per booked session, so the screen can
-- say when it starts, how long until it starts, and where to join.
--
-- NOTHING HERE IS CALENDLY-SHAPED
-- ------------------------------
-- Calendly's webhooks need its Standard plan; the free tier has no webhooks, no post-booking
-- redirect and one active event type, so it cannot serve the 30- and 60-minute sessions at all.
-- Which scheduler the owner ends up paying for (or replacing with a free Google Calendar
-- appointment schedule) is therefore an open question, and this table is written so that the
-- answer never reaches it:
--
--   external_id         the provider's own id for this booking-for-this-person. Calendly's
--                       invitee uri; a Google Calendar event id; whatever the next one calls it.
--                       Unique, and the reason a delivery repeated twice writes one row.
--   external_event_id   the provider's id for the session itself, which several people could
--                       in principle share.
--   source              a short slug naming the ingestion path, validated by shape and not
--                       against a list — so adding one is a new caller, never a migration.
--                       In use or foreseen: 'calendly_webhook', 'google_calendar', 'admin'.
--
-- Only `calendly_webhook` exists today (supabase/functions/calendly-webhook/), and only on a paid
-- Calendly plan. A second source fills the same columns through the same two functions below.
--
-- IDENTITY, AND WHY AN EMAIL HERE GRANTS NOTHING
-- ----------------------------------------------
-- A scheduler knows a person by the address typed into its form, which anybody can type. So the
-- address is a *join key*, never an identity: a row may exist for an address that never signs in,
-- and it does nothing until somebody holds a confirmed session for that address. Reading is
-- `public.current_email()`, which resolves through `auth.uid()` → a confirmed, unbanned
-- `auth.users` row — exactly as purchases (0001) and subscriptions (0005) do it. Booking a slot
-- therefore cannot grant access to anything; it only makes a card appear for the person who can
-- actually prove that address.
--
-- IDEMPOTENCY AND RESCHEDULES
-- ---------------------------
-- `external_id` is unique, so a delivery repeated twice writes once. Rescheduling is the awkward
-- case, because at least one provider does not have an event for it: Calendly cancels the old
-- invitee (with `rescheduled: true`) and creates a new one carrying `old_invitee`, i.e. a new
-- `external_id` for the same session. `apply_coach_booking()` takes that predecessor id and
-- *moves* the existing row onto the new booking instead of adding a second one. A cancellation
-- marks the row cancelled and keeps it: the person should see that the session they had is gone,
-- and the coach should still see that it happened.
-- =============================================================================

create table if not exists public.coach_bookings (
  id                   uuid primary key default gen_random_uuid(),
  -- The address the person gave the scheduler. A join key, not an identity — see the header.
  email                citext not null,
  -- The provider's ids. `external_id` is unique per booking and is the idempotency key.
  external_id          text not null unique,
  external_event_id    text not null,
  -- Set when this row replaced an earlier booking, kept so support can follow a reschedule back.
  previous_external_id text,
  starts_at            timestamptz not null,
  ends_at              timestamptz not null,
  -- The IANA zone the person booked in, as the provider recorded it. See `my_coach_bookings`.
  timezone             text,
  -- Where to join. A conference location carries `join_url`; a physical one carries text instead,
  -- so the two are kept apart rather than squeezed into one column that means different things.
  join_url             text,
  location_kind        text,
  location_text        text,
  cancel_url           text,
  reschedule_url       text,
  status               text not null default 'active' check (status in ('active', 'cancelled')),
  cancel_reason        text,
  event_name           text,
  source               text not null default 'calendly_webhook',
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

comment on table public.coach_bookings is
  'One-to-one sessions booked with the coach, whatever scheduler they came from. A reschedule moves the row; a cancellation keeps it.';

alter table public.coach_bookings drop constraint if exists coach_bookings_email_len;
alter table public.coach_bookings add constraint coach_bookings_email_len
  check (length(email::text) <= 254) not valid;
alter table public.coach_bookings drop constraint if exists coach_bookings_external_id_len;
alter table public.coach_bookings add constraint coach_bookings_external_id_len
  check (length(external_id) between 1 and 400) not valid;
alter table public.coach_bookings drop constraint if exists coach_bookings_external_event_id_len;
alter table public.coach_bookings add constraint coach_bookings_external_event_id_len
  check (length(external_event_id) between 1 and 400) not valid;
alter table public.coach_bookings drop constraint if exists coach_bookings_replaces_len;
alter table public.coach_bookings add constraint coach_bookings_replaces_len
  check (previous_external_id is null or length(previous_external_id) <= 400) not valid;
alter table public.coach_bookings drop constraint if exists coach_bookings_order;
alter table public.coach_bookings add constraint coach_bookings_order
  check (ends_at > starts_at) not valid;
-- An IANA zone name, loosely: enough to keep junk out of Intl.DateTimeFormat on the client.
alter table public.coach_bookings drop constraint if exists coach_bookings_timezone_fmt;
alter table public.coach_bookings add constraint coach_bookings_timezone_fmt
  check (timezone is null or timezone ~ '^[A-Za-z][A-Za-z0-9+_/-]{1,63}$') not valid;
/*
 * Every url the app may render as a link has to be https. The payload is attacker-shaped in the
 * worst case, and a `javascript:` or `data:` value that reaches an anchor is the whole exploit —
 * so it is refused at the column rather than sanitised at every call site.
 */
alter table public.coach_bookings drop constraint if exists coach_bookings_join_url_https;
alter table public.coach_bookings add constraint coach_bookings_join_url_https
  check (join_url is null or (join_url ~ '^https://' and length(join_url) <= 2000)) not valid;
alter table public.coach_bookings drop constraint if exists coach_bookings_cancel_url_https;
alter table public.coach_bookings add constraint coach_bookings_cancel_url_https
  check (cancel_url is null or (cancel_url ~ '^https://' and length(cancel_url) <= 2000)) not valid;
alter table public.coach_bookings drop constraint if exists coach_bookings_reschedule_url_https;
alter table public.coach_bookings add constraint coach_bookings_reschedule_url_https
  check (reschedule_url is null or (reschedule_url ~ '^https://' and length(reschedule_url) <= 2000)) not valid;
/*
 * `location_kind` is capped rather than enumerated. Calendly's set today is physical,
 * outbound_call, inbound_call, google_conference, zoom_conference, gotomeeting,
 * microsoft_teams_conference, custom and ask_invitee — and it grows whenever they add a
 * conferencing partner. An enum here would turn that into a failed webhook and a booking the
 * person never sees; the client already treats "has a join_url" as the thing that matters.
 */
alter table public.coach_bookings drop constraint if exists coach_bookings_location_kind_len;
alter table public.coach_bookings add constraint coach_bookings_location_kind_len
  check (location_kind is null or length(location_kind) <= 40) not valid;
alter table public.coach_bookings drop constraint if exists coach_bookings_location_text_len;
alter table public.coach_bookings add constraint coach_bookings_location_text_len
  check (location_text is null or length(location_text) <= 500) not valid;
alter table public.coach_bookings drop constraint if exists coach_bookings_event_name_len;
alter table public.coach_bookings add constraint coach_bookings_event_name_len
  check (event_name is null or length(event_name) <= 200) not valid;
alter table public.coach_bookings drop constraint if exists coach_bookings_cancel_reason_len;
alter table public.coach_bookings add constraint coach_bookings_cancel_reason_len
  check (cancel_reason is null or length(cancel_reason) <= 500) not valid;
/*
 * `source` is checked for shape, not for membership of a list, and deliberately — an enumerated
 * constraint would mean a migration every time the owner changes her mind about which scheduler
 * she is paying for, which is exactly the change this table exists to absorb. `subscriptions.source`
 * (0005) is capped the same way for the same reason.
 */
alter table public.coach_bookings drop constraint if exists coach_bookings_source_fmt;
alter table public.coach_bookings add constraint coach_bookings_source_fmt
  check (source ~ '^[a-z][a-z0-9_]{1,39}$') not valid;

-- The only query the app makes: this person's sessions, soonest first.
create index if not exists coach_bookings_email_starts_idx
  on public.coach_bookings (email, starts_at desc);
-- The coach's list: what is coming up, across everybody.
create index if not exists coach_bookings_status_starts_idx
  on public.coach_bookings (status, starts_at);

drop trigger if exists coach_bookings_touch on public.coach_bookings;
create trigger coach_bookings_touch
  before update on public.coach_bookings
  for each row execute function public.set_updated_at();

alter table public.coach_bookings enable row level security;

-- The coach and the owner read and write everything, as with purchases and subscriptions.
drop policy if exists "coach_bookings: admins all" on public.coach_bookings;
create policy "coach_bookings: admins all"
  on public.coach_bookings for all
  to authenticated
  using (public.is_admin())
  with check (public.is_admin());

/*
 * Everybody else reads their own rows and only their own. This is a read policy and there is no
 * matching write policy on purpose: bookings are made in the scheduler and written by ingestion with
 * the service role. A signed-in person can never insert, move or cancel a booking through the API,
 * including their own — that would be a way to write a session into somebody else's account.
 */
drop policy if exists "coach_bookings: owner select" on public.coach_bookings;
create policy "coach_bookings: owner select"
  on public.coach_bookings for select
  to authenticated
  using (email = public.current_email());

revoke all on public.coach_bookings from anon, authenticated;
grant select, insert, update, delete on public.coach_bookings to authenticated;

-- -----------------------------------------------------------------------------
-- my_coach_bookings — the signed-in person's own sessions, soonest first.
--
-- `timezone` is passed through rather than used here: the row records the zone the person booked
-- in, but the app shows the time in the zone of the device they are holding, which is the one
-- they are actually living in when the session starts. The stored value is the fallback for a
-- browser that reports nothing useful. See src/lib/coach/booking.ts.
-- -----------------------------------------------------------------------------
drop view if exists public.my_coach_bookings;
create view public.my_coach_bookings
with (security_invoker = false)
as
  select b.id, b.starts_at, b.ends_at, b.timezone, b.join_url, b.location_kind, b.location_text,
         b.cancel_url, b.reschedule_url, b.status, b.event_name
  from public.coach_bookings b
  where b.email = public.current_email()
  order by b.starts_at;

revoke all on public.my_coach_bookings from anon, authenticated;
grant select on public.my_coach_bookings to authenticated;

-- -----------------------------------------------------------------------------
-- apply_coach_booking — a booking was made, or moved. Called by the ingestion path with the
-- service role; never by a signed-in user.
--
-- Idempotent on `p_external_id`: the same delivery twice writes one row. When `p_previous_external_id`
-- names a row we already have, that row is *moved* onto the new booking — a reschedule is the same
-- session at a new time, not a second session. Provider-neutral: see the header.
-- -----------------------------------------------------------------------------
create or replace function public.apply_coach_booking(
  p_email                text,
  p_external_id          text,
  p_external_event_id    text,
  p_starts_at            timestamptz,
  p_ends_at              timestamptz,
  p_timezone             text default null,
  p_join_url             text default null,
  p_location_kind        text default null,
  p_location_text        text default null,
  p_cancel_url           text default null,
  p_reschedule_url       text default null,
  p_event_name           text default null,
  p_previous_external_id text default null,
  p_source               text default 'calendly_webhook'
)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_email    citext;
  v_external  text;
  v_previous text;
  v_source   text;
  v_id       uuid;
begin
  -- Only the service role (the webhook) and the SQL editor: never a signed-in user.
  if coalesce(current_setting('request.jwt.claims', true), '') <> ''
     and coalesce(current_setting('request.jwt.claims', true)::json ->> 'role', '') <> 'service_role' then
    raise exception 'not_allowed' using errcode = '42501';
  end if;

  v_email   := public.normalize_email(p_email);
  v_external := nullif(trim(coalesce(p_external_id, '')), '');
  if v_external is null then
    raise exception 'invalid_external_id' using errcode = 'P0001';
  end if;
  if p_starts_at is null or p_ends_at is null or p_ends_at <= p_starts_at then
    raise exception 'invalid_times' using errcode = 'P0001';
  end if;
  -- By shape, like the column: a new ingestion path is a new caller, not a new migration.
  if p_source is null or p_source !~ '^[a-z][a-z0-9_]{1,39}$' then
    raise exception 'invalid_source' using errcode = 'P0001';
  end if;
  v_source   := p_source;
  v_previous := nullif(trim(coalesce(p_previous_external_id, '')), '');

  -- A reschedule: move the row we already hold onto the new booking rather than inserting.
  if v_previous is not null and v_previous <> v_external then
    update public.coach_bookings
       set email                = v_email,
           external_id          = v_external,
           external_event_id    = p_external_event_id,
           previous_external_id = v_previous,
           starts_at            = p_starts_at,
           ends_at              = p_ends_at,
           timezone             = p_timezone,
           join_url             = p_join_url,
           location_kind        = p_location_kind,
           location_text        = p_location_text,
           cancel_url           = p_cancel_url,
           reschedule_url       = p_reschedule_url,
           status               = 'active',
           cancel_reason        = null,
           event_name           = coalesce(p_event_name, event_name),
           source               = v_source
     where external_id = v_previous
     returning id into v_id;
    if v_id is not null then
      return v_id;
    end if;
    -- The earlier booking never reached us (the webhook was added mid-flight, or the first
    -- delivery failed). Fall through and record the new one on its own.
  end if;

  insert into public.coach_bookings as cb (
    email, external_id, external_event_id, previous_external_id, starts_at, ends_at, timezone,
    join_url, location_kind, location_text, cancel_url, reschedule_url, status, event_name, source
  )
  values (
    v_email, v_external, p_external_event_id, v_previous, p_starts_at, p_ends_at, p_timezone,
    p_join_url, p_location_kind, p_location_text, p_cancel_url, p_reschedule_url, 'active',
    p_event_name, v_source
  )
  on conflict (external_id) do update
    set email                = excluded.email,
        external_event_id    = excluded.external_event_id,
        previous_external_id = coalesce(excluded.previous_external_id, cb.previous_external_id),
        starts_at            = excluded.starts_at,
        ends_at              = excluded.ends_at,
        timezone             = excluded.timezone,
        join_url             = excluded.join_url,
        location_kind        = excluded.location_kind,
        location_text        = excluded.location_text,
        cancel_url           = excluded.cancel_url,
        reschedule_url       = excluded.reschedule_url,
        -- A replayed "booked" delivery never resurrects a booking cancelled afterwards: the
        -- cancellation is the later fact about the same external id.
        status               = cb.status,
        event_name           = coalesce(excluded.event_name, cb.event_name),
        source               = excluded.source,
        updated_at           = now()
  returning cb.id into v_id;

  return v_id;
end;
$$;

comment on function public.apply_coach_booking(text, text, text, timestamptz, timestamptz, text, text, text, text, text, text, text, text, text) is
  'Service-role only: record or move a coach booking. Idempotent per external id; a reschedule moves the existing row.';

revoke execute on function public.apply_coach_booking(text, text, text, timestamptz, timestamptz, text, text, text, text, text, text, text, text, text)
  from public, anon, authenticated;
grant execute on function public.apply_coach_booking(text, text, text, timestamptz, timestamptz, text, text, text, text, text, text, text, text, text)
  to service_role;

-- -----------------------------------------------------------------------------
-- cancel_coach_booking — the person (or the coach) cancelled. The row stays: the person needs
-- to see that the session is gone, and the coach needs the history.
--
-- Returns the row id, or null when the booking was never recorded here — which is normal for a
-- cancellation that arrives for a booking made before ingestion was switched on, and is not an
-- error the caller should retry.
-- -----------------------------------------------------------------------------
create or replace function public.cancel_coach_booking(
  p_external_id text,
  p_reason      text default null
)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_external text;
  v_id      uuid;
begin
  if coalesce(current_setting('request.jwt.claims', true), '') <> ''
     and coalesce(current_setting('request.jwt.claims', true)::json ->> 'role', '') <> 'service_role' then
    raise exception 'not_allowed' using errcode = '42501';
  end if;

  v_external := nullif(trim(coalesce(p_external_id, '')), '');
  if v_external is null then
    raise exception 'invalid_external_id' using errcode = 'P0001';
  end if;

  update public.coach_bookings
     set status        = 'cancelled',
         cancel_reason = left(nullif(trim(coalesce(p_reason, '')), ''), 500)
   where external_id = v_external
   returning id into v_id;

  return v_id;
end;
$$;

comment on function public.cancel_coach_booking(text, text) is
  'Service-role only: mark a coach booking cancelled. Never deletes; null when the booking is unknown.';

revoke execute on function public.cancel_coach_booking(text, text) from public, anon, authenticated;
grant execute on function public.cancel_coach_booking(text, text) to service_role;

-- =============================================================================
-- 0015_drop_steps.sql — steps leave the product.
-- =============================================================================

-- =============================================================================
-- 0015 — steps leave the product.
--
-- WHY. The owner's rule, in her own words: «Он либо стекается либо его нет
-- вообще. Потому что пользователь не будет заниматься трекингом одних и тех же
-- шагов в разных приложениях.» Either the step count syncs from the phone's own
-- health app, or the feature does not exist.
--
-- It cannot sync. Forma is a Telegram Mini App — a WebView — and:
--   • Apple HealthKit is a native iOS framework with no browser API at all. The
--     only way to read it is to ship a native app.
--   • Google Fit's REST API stopped accepting new developer registrations on
--     1 May 2024 and shuts down at the end of 2026, so it cannot even be applied
--     for.
--   • Health Connect, its replacement, reads on-device data from a native
--     Android app. There is no web endpoint.
--   • The Google Health API (the former Fitbit Web API) is a cloud API for
--     Fitbit and Pixel Watch accounts — not the phone's Health app, and not
--     something a person without one of those devices has anything in.
--
-- So the number could only ever be typed in by hand, which is what the app did,
-- and which is the arrangement the rule rejects. Everything that counted steps
-- is therefore removed rather than left switched off.
--
-- ⚠️ THIS DROPS DATA AND CANNOT BE UNDONE. `public.daily_logs` holds every day
-- anyone ever logged, together with the screenshot path that went with it. Take
-- a backup first if any of it is worth keeping — on a project that has not
-- launched, it is test data and it is not.
--
-- Objects in the `proofs` bucket under `steps/<user_id>/…` are NOT deleted here:
-- SQL cannot remove files from Storage. After this runs they are unreachable
-- (the policies that granted access are gone) and can be deleted from the
-- Storage screen, or left to sit.
--
-- Safe to re-run: every drop is `if exists`, and both functions are rewritten
-- with `create or replace`.
-- =============================================================================

begin;

-- -----------------------------------------------------------------------------
-- 1) The leaderboard stops counting step points.
--
-- Same function, minus the `d` CTE that summed `daily_logs` and minus the cap
-- that clamped it. A course board never counted steps in the first place
-- (`where p_course_id is null`), so only the global board changes.
-- -----------------------------------------------------------------------------
create or replace function public.get_leaderboard(
  p_period    text default 'week',
  p_course_id text default null,
  p_limit     int  default 100
)
returns table (
  user_id      uuid,
  display_name text,
  avatar_seed  text,
  points       bigint,
  rank         bigint,
  is_me        boolean
)
language plpgsql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  -- Defence in depth: the engine ceiling (basePoints 250 × harder 1.25 × streak 1.2).
  -- workout_sessions_guard already clamps per workout, but the board is the one place
  -- every athlete sees, so it clamps again.
  c_max_session_points constant int := 375;

  v_me      uuid := auth.uid();
  v_limit   int  := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_week_ts timestamp;
  v_from    timestamptz;
begin
  if v_me is null then
    raise exception 'not_authenticated' using errcode = '42501';
  end if;

  if p_period is null or p_period not in ('week', 'all') then
    raise exception 'invalid_period' using errcode = 'P0001';
  end if;

  if p_course_id is not null and p_course_id !~ '^[a-z0-9_]{2,40}$' then
    raise exception 'invalid_course' using errcode = 'P0001';
  end if;

  -- Monday 00:00 UTC of the current ISO week.
  v_week_ts := date_trunc('week', now() at time zone 'utc');
  v_from    := v_week_ts at time zone 'utc';

  return query
  with totals as (
    select ws.user_id as uid,
           sum(least(greatest(ws.points, 0), c_max_session_points))::bigint as pts
    from public.workout_sessions ws
    where ws.completed_at is not null
      and ws.completed_at <= now()
      and (p_period = 'all' or ws.completed_at >= v_from)
      and (p_course_id is null or ws.course_id = p_course_id)
    group by ws.user_id
  ),
  ranked as (
    select t.uid, t.pts, rank() over (order by t.pts desc, t.uid) as rnk
    from totals t
    where t.pts > 0
  ),
  top as (
    select r.uid, r.pts, r.rnk from ranked r order by r.rnk, r.uid limit v_limit
  ),
  me as (
    select r.uid, r.pts, r.rnk from ranked r where r.uid = v_me
    union all
    -- Caller without points yet: last place, 0 points.
    select v_me, 0::bigint, (select count(*) from ranked) + 1
    where not exists (select 1 from ranked r where r.uid = v_me)
  ),
  rows_out as (
    select * from top
    union
    select * from me
  )
  select
    ro.uid,
    -- Clamped again on the way out: this row is relayed to every other athlete.
    left(coalesce(nullif(trim(p.display_name), ''), 'Athlete ' || left(ro.uid::text, 4)), 60),
    left(coalesce(p.avatar_seed, left(ro.uid::text, 8)), 64),
    ro.pts,
    ro.rnk,
    ro.uid = v_me
  from rows_out ro
  left join public.profiles p on p.id = ro.uid
  order by ro.rnk, ro.uid;
end;
$$;

revoke execute on function public.get_leaderboard(text, text, int) from public, anon;
grant execute on function public.get_leaderboard(text, text, int) to authenticated;

-- -----------------------------------------------------------------------------
-- 2) All-time totals stop adding step points.
-- -----------------------------------------------------------------------------
create or replace function public.get_my_totals()
returns table (points bigint, workouts bigint, minutes bigint)
language sql
stable
security invoker
set search_path = pg_catalog, public, extensions
as $$
  select
    coalesce((select sum(ws.points) from public.workout_sessions ws
              where ws.user_id = auth.uid() and ws.completed_at is not null), 0)::bigint as points,
    coalesce((select count(*) from public.workout_sessions ws
              where ws.user_id = auth.uid() and ws.completed_at is not null), 0)::bigint as workouts,
    coalesce((select sum(ws.duration_sec) from public.workout_sessions ws
              where ws.user_id = auth.uid() and ws.completed_at is not null), 0)::bigint / 60 as minutes;
$$;

revoke execute on function public.get_my_totals() from public, anon;
grant execute on function public.get_my_totals() to authenticated;

-- -----------------------------------------------------------------------------
-- 3) The storage policies for step screenshots, and the function behind them.
--
-- The `proofs` bucket itself stays — the club's own proof lives in it under
-- `marathon/…` and is governed by 0011's policies, which are untouched.
-- -----------------------------------------------------------------------------
drop policy if exists "proofs: steps own read"   on storage.objects;
drop policy if exists "proofs: steps own insert" on storage.objects;
drop policy if exists "proofs: steps own update" on storage.objects;
drop policy if exists "proofs: steps own delete" on storage.objects;

drop function if exists public.owns_step_proof_path(text);

-- -----------------------------------------------------------------------------
-- 4) The table, its trigger and its scoring function.
--
-- The trigger goes with the table (`drop table` takes it), but the two functions
-- are separate objects and have to be named.
-- -----------------------------------------------------------------------------
drop table if exists public.daily_logs cascade;

drop function if exists public.daily_logs_set_points();
drop function if exists public.steps_points(int, int);

-- -----------------------------------------------------------------------------
-- 5) The rest day's step goal, in the course builder.
--
-- A rest day was completed by reaching a number of steps; it is now simply a day
-- that is marked as taken. The column is dropped rather than ignored so the
-- admin screen and the published bundle cannot disagree about whether it exists.
-- -----------------------------------------------------------------------------
-- `if exists` on the table as well: this file is order-independent, and a throwaway database
-- built for the smoke suite has 0001-0004 but not yet 0008, which creates this table.
alter table if exists public.admin_course_days drop column if exists steps_goal;

commit;

-- =============================================================================
-- 0016_club_membership.sql — the club is a subscription, not a cohort.
-- =============================================================================

-- =============================================================================
-- 0016 — the club is a subscription, not a cohort.
--
-- The defect this fixes, in the owner's words: «У нас каждую неделю новый
-- лидерборд для всех и все. Если ты в клубе то ты участвуешь. Если нет то нет.»
--
-- What the code did instead: the club was a `marathons` row and you were in it
-- only if somebody had written your email into `marathon_members` by hand — the
-- `club-join` workflow, reading a list out of a repository secret. That is
-- inherited from the marathon this schema was built for, where the coach ran a
-- closed cohort and typed the names in. A club has no cohort. Paying IS the
-- membership.
--
-- The visible symptom: the coach opened the club tab and got «Ты в клубе» over
-- the sales screen — `gameAccess` let him past the gate (he is entitled), and
-- then `my_marathons()` found no row for his address and returned nothing, so
-- there was no task, no board and no challenge. Everything built to the Figma
-- mockups lives inside that screen, so none of it was reachable.
--
-- Three things here, and nothing is deleted:
--
--   1. `marathons.is_club` — which row IS the club. One at a time.
--   2. `days` may exceed 100, so the club does not end.
--   3. `club_access()` and `join_club()` — the gate, in the database.
--
-- **The gate is re-implemented server-side on purpose.** `gameAccess` (the
-- TypeScript) decides whether to *draw* the tab; it cannot decide who gets a row
-- in `marathon_members`, because it runs on the customer's phone. An RPC that
-- took the client's word for it would be a paywall anyone signed in could walk
-- through by calling it directly. So `club_access()` reads the same two facts
-- from the tables — a live subscription, or a course activated inside the trial
-- window — and the two definitions have to be kept in step. `GAME_TRIAL_DAYS`
-- in src/app/features/marathon/gameAccess.ts is the other half of this rule.
--
-- ## Calendar weeks without touching the scoring
--
-- The owner asked for the leaderboard to reset on calendar weeks. It already
-- resets every seven days — `marathon_week_of(day)` is `((day - 1) / 7) + 1`,
-- counted from `starts_on` — so the whole of "calendar weeks" is **starting the
-- club on a Monday**. Then day 1 is a Monday, days 1..7 are one calendar week,
-- and every bucket after it is too.
--
-- That is deliberately not a rewrite of `marathon_week_of`. Every point the club
-- has ever scored is derived through it (`marathon_scores` filters the week's
-- tasks with it, and points are computed rather than stored), so changing it
-- rewrites history for everyone. A Monday start gives the identical result for
-- the price of a date.
--
-- Requires 0011_marathon.sql.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Which marathon is the club.
--
-- A flag rather than a magic slug: `join_club()` has to find it from inside the
-- database, and a string constant compiled into a function is the kind of thing
-- that survives a rename of the row it points at and then silently matches
-- nothing.
--
-- The partial unique index is the whole guard. Two clubs would mean a member
-- joined to one of them and scored on the other, and the failure would look like
-- an empty board rather than like a duplicate.
-- -----------------------------------------------------------------------------
alter table public.marathons
  add column if not exists is_club boolean not null default false;

comment on column public.marathons.is_club is
  'The one continuous club. Anyone whose subscription (or course trial) is live joins it by opening the tab; every other marathon is a closed cohort the coach fills by hand.';

create unique index if not exists marathons_one_club_idx
  on public.marathons (is_club) where is_club;

-- -----------------------------------------------------------------------------
-- 2. The club does not end.
--
-- `days` was capped at 100 with the comment "far past anything a daily-proof
-- format survives; it is a guard rail, not a target" — true of a marathon, and
-- exactly wrong for a club that runs for as long as people pay. Past `days` the
-- day counter stops (`my_marathons` takes `least(day_index, days)`), so a club
-- on 7 days would sit on day 7 for ever, repeating day 7's task.
--
-- The guard rail stays, ten years out. A number this size is still a typo
-- detector; it just is not a horizon any more.
-- -----------------------------------------------------------------------------
alter table public.marathons drop constraint if exists marathons_days_check;
alter table public.marathons add constraint marathons_days_check
  check (days between 1 and 3700);

-- -----------------------------------------------------------------------------
-- 3a. club_access — may the caller be in the club right now?
--
-- The same two grounds the app draws the tab on, read from the tables:
--
--   • a live subscription — `subscription_live()` is already the one definition
--     of that, and a cancelled subscription stays live until the period it paid
--     for runs out;
--   • a course activated within the trial window — `purchases.activated_at` is
--     stamped when the coach confirms the payment, so a refunded course takes
--     its trial with it and no second table can drift out of step.
--
-- Admins always pass: the coach has to be able to open the club he runs without
-- buying his own subscription, and he is the reason this bug was reported.
-- -----------------------------------------------------------------------------
create or replace function public.club_access()
returns boolean
language sql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
  select
    public.is_admin()
    or exists (
      select 1 from public.subscriptions s
      where s.email = public.current_email()
        and public.subscription_live(s.status, s.expires_at)
    )
    or exists (
      select 1 from public.purchases p
      where p.email = public.current_email()
        and p.status = 'active'
        and p.activated_at is not null
        -- 7 days, matching GAME_TRIAL_DAYS in gameAccess.ts. The two are one rule
        -- in two places; change them together.
        and p.activated_at > now() - interval '7 days'
    );
$$;

revoke execute on function public.club_access() from public, anon;
grant execute on function public.club_access() to authenticated;

comment on function public.club_access() is
  'Server-side twin of gameAccess(): a live subscription, a course inside its 7-day trial, or an admin.';

-- -----------------------------------------------------------------------------
-- 3b. join_club — put the caller in the club, if they are entitled to be.
--
-- Idempotent, and safe to call on every open of the tab: it either does nothing
-- or reactivates a row. Returns the club's id so the caller can tell "you are in"
-- from "there is no club" without a second round trip.
--
-- `team_id` is null and stays null. The club is `team_size = 1` — «каждый сам за
-- себя» — and `marathon_members_check_team` refuses a member pointing at a team
-- in that mode, so a row carrying one would not insert at all.
--
-- `display_name` is left null on purpose: the board then reads the name off the
-- person's own profile, which is the name they chose for themselves.
--
-- A member the coach removed by hand is **not** silently let back in. `status`
-- is only lifted back to 'active' for a row this function could have written —
-- one with no note and no display name the coach set. Anything he touched is his
-- decision, and a self-join that undoes a removal would be the product arguing
-- with its own admin.
-- -----------------------------------------------------------------------------
create or replace function public.join_club()
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $$
declare
  v_club  uuid;
  v_email citext := public.current_email();
begin
  if v_email is null or not public.club_access() then
    return null;
  end if;

  select id into v_club
  from public.marathons
  where is_club and status = 'active'
  limit 1;

  if v_club is null then
    return null;
  end if;

  insert into public.marathon_members (marathon_id, email, team_id, status)
  values (v_club, v_email, null, 'active')
  on conflict (marathon_id, email) do update
    set status = case
      when public.marathon_members.status = 'removed'
       and public.marathon_members.note is null
       and public.marathon_members.display_name is null
      then 'active'
      else public.marathon_members.status
    end
  returning marathon_id into v_club;

  return v_club;
end;
$$;

revoke execute on function public.join_club() from public, anon;
grant execute on function public.join_club() to authenticated;

comment on function public.join_club() is
  'Self-join the club on the strength of a live subscription or a course trial. Idempotent; returns the club id, or null when there is no club or no entitlement.';

-- -----------------------------------------------------------------------------
-- 4. The club itself.
--
-- A row of its own rather than promoting `klub_test`, and that is the whole
-- reason it is here: the test week is seeded with seven fictional members on
-- `@example.test`, and promoting it would put them on the leaderboard of every
-- paying member. The test week is left exactly as it is — still running, still
-- the owner's to play with, archived by hand whenever she is done with it.
--
-- `starts_on` is **this week's Monday**, which is the entire implementation of
-- "the leaderboard resets on calendar weeks": `marathon_week_of` buckets seven
-- days from the start, so a Monday start makes every bucket a Monday-to-Sunday
-- week. `date_trunc('week', …)` is ISO — Monday — in every locale, unlike
-- `extract(dow …)`, which counts from Sunday.
--
-- Ten years of `days`, so the club does not end. No tasks: the coach writes the
-- day's task in the admin, and a club seeded with invented ones would be putting
-- words in his mouth on a screen members pay to read.
--
-- Idempotent on the slug, and it deliberately does **not** rewrite `starts_on`
-- on a re-run. Moving the start would shift every task's day index and rewrite
-- which week every point was earned in.
-- -----------------------------------------------------------------------------
insert into public.marathons (
  slug, title, description, status, starts_on, days, team_size, timezone, due_time, prize, is_club
)
values (
  'club',
  'Клуб маленьких шагов',
  'Одно небольшое задание в день и общая таблица. Каждую неделю таблица начинается заново.',
  'active',
  date_trunc('week', current_date)::date,
  3650,
  1,                      -- каждый сам за себя
  'Europe/Moscow',
  '22:00',
  'Час с тренером и создателем Forma',
  true
)
on conflict (slug) do update set
  status   = 'active',
  days     = greatest(public.marathons.days, 3650),
  is_club  = true;

-- -----------------------------------------------------------------------------
-- 5. my_marathons carries is_club.
--
-- Two marathons can be running at once — the club, and a closed round the coach
-- is putting people into by hand — and the app has to know which is which. It
-- used to take "the first active one", ordered by start date, which would hand a
-- member the test week simply because it started later.
--
-- Same body as 0011 with one column added; replacing the function is the only
-- way Postgres allows a change to its return type, so the drop is required and
-- carries no data.
-- -----------------------------------------------------------------------------
drop function if exists public.my_marathons();

create or replace function public.my_marathons()
returns table (
  id          uuid,
  slug        text,
  title       text,
  description text,
  status      text,
  starts_on   date,
  days        int,
  team_size   int,
  prize       text,
  day_index   int,
  week        int,
  total_weeks int,
  member_id   uuid,
  team_id     uuid,
  team_name   text,
  is_club     boolean
)
language sql
stable
security definer
set search_path = pg_catalog, public, extensions
as $$
  select
    m.id, m.slug, m.title, m.description, m.status, m.starts_on, m.days, m.team_size, m.prize,
    least(public.marathon_day_index(m.id), m.days) as day_index,
    public.marathon_week_of(least(public.marathon_day_index(m.id), m.days)) as week,
    public.marathon_week_of(m.days) as total_weeks,
    mem.id, mem.team_id, t.name, m.is_club
  from public.marathons m
  join public.marathon_members mem
    on mem.marathon_id = m.id
   and mem.status = 'active'
   and mem.email = public.current_email()
  left join public.marathon_teams t on t.id = mem.team_id
  where m.status in ('active', 'finished')
  order by m.is_club desc, m.starts_on desc;
$$;

revoke execute on function public.my_marathons() from public, anon;
grant execute on function public.my_marathons() to authenticated;

-- =============================================================================
-- 0017_club_first_weeks.sql — the club's first three weeks of tasks.
-- =============================================================================

-- =============================================================================
-- 0017 — the club's first three weeks of tasks.
--
-- A one-off fill, so the club is not an empty screen on the day people are let
-- into it. **Everything after this is written in the admin**, one task a
-- morning, by the coach — this file is a runway, not a schedule, and nothing
-- here should ever be edited to change next week.
--
-- ## What is written, and what is deliberately not
--
-- Twenty-one tasks, one a day, keyed to `day_index` 1..21 — the club started on
-- a Monday, so those are exactly three calendar weeks. Only days from **today
-- onwards** are inserted: a task on a day that has already passed is a row
-- nobody could have delivered, and it would sit in the week's scoring as points
-- everybody missed.
--
-- They are small on purpose, and none of them is a maximum. «Не выжимай
-- максимум» is the instruction the onboarding gives in the coach's voice, and a
-- club task that contradicted it on day two would be the product arguing with
-- itself. So: a walk, a stretch, a glass of water, a number of squats spread
-- across a day — things anyone can do in the clothes they are wearing, and
-- things a person with a bad knee can scale without being told to.
--
-- No `media_url` on any of them. The card draws the coach's picture above the
-- title, and the honest answer to "which picture" is that he has not taken them
-- yet; the same stock frame twenty-one times would read as a fault rather than
-- as a photograph. The field is in the admin and the day he attaches one it
-- appears.
--
-- Nothing here claims a benefit. No «сожжёшь N калорий», no «за две недели
-- уйдёт», no percentages — `docs/SPEC.md` forbids invented statistics, and the
-- screen this text lands on is one people pay to read.
--
-- ## The shape
--
--   rule = 'per_member'   the club is team_size = 1: you deliver, you score.
--   proof_kind mostly 'done'; a few numbers where a figure is the point, one
--   photograph for the coach only, and a line of text at the end of each week.
--   points 8..15, heavier where the task costs more of the day.
--
-- Idempotent: the range is cleared first, but only of tasks **nobody has
-- delivered against** — a task with proof on it belongs to the people who did
-- it, and deleting it would cascade their submissions away.
--
-- Requires 0016_club_membership.sql.
-- =============================================================================

do $$
declare
  v_club  uuid;
  v_today int;
begin
  select id into v_club from public.marathons where is_club limit 1;
  if v_club is null then
    raise exception 'no_club' using hint = 'Run 0016_club_membership.sql first.';
  end if;

  v_today := greatest(public.marathon_day_index(v_club), 1);

  delete from public.marathon_tasks t
  where t.marathon_id = v_club
    and t.day_index between v_today and 21
    and not exists (
      select 1 from public.marathon_submissions s where s.task_id = t.id
    );

  insert into public.marathon_tasks
    (marathon_id, day_index, sort_order, title, body, proof_kind, unit, target_num, rule, points,
     proof_visibility)
  select
    v_club, v.day, 0, v.title, v.body, v.proof_kind, v.unit, v.target_num, 'per_member', v.points,
    /*
     * A photograph goes to the coach and to nobody else, and it is derived here rather than typed
     * per row so the two can never disagree: day 13's body says «видит только тренер», and a row
     * that left the default 'team' on it would make the screen lie about who is looking. Everything
     * else is a fact and a figure, which the board shows anyway.
     */
    case when v.proof_kind = 'media' then 'coach' else 'team' end
  from (values
    -- --- week 1 -------------------------------------------------------------
